insert into ponew values
(1, 1, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A PACU nurse hands over a patient to the ward nurse. The handover should include:', '["Only the time of arrival in the recovery room", "Only the patient''s name and hospital number", "Procedure, anaesthesia, drugs, fluids, concerns and plan", "Only the surgeon''s name and phone number, in case the ward needs help"]'::jsonb, 2, 'A structured tool such as SBAR reduces omissions.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 2, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient with severe cirrhosis of the liver develops hepatorenal syndrome. Which of the following nursing assessment data would support this?', '["Oliguria and azotemia", "Metabolic alkalosis", "Decreased urinary concentration", "Weight gain of less than 1kg per week"]'::jsonb, 0, 'Oliguria with rising nitrogenous waste (azotaemia) is the hallmark of hepatorenal syndrome.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 3, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'The thick ascending limb of the loop of Henle actively reabsorbs sodium, potassium, and chloride via which transporter, the target of loop diuretics?', '["Na+-Cl- cotransporter (NCC)", "Na+-K+-2Cl- cotransporter (NKCC2)", "Epithelial sodium channel (ENaC)", "Sodium-glucose cotransporter (SGLT2)"]'::jsonb, 1, 'NKCC2 on the apical membrane of thick ascending limb cells reabsorbs sodium, potassium, and chloride and is the site of action of loop diuretics such as furosemide.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 4, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'During suctioning of an intubated patient, the nurse should limit each suction pass to approximately:', '["No time limit is necessary", "60 seconds", "5 minutes", "10–15 seconds"]'::jsonb, 3, 'Suctioning should be limited to about 10–15 seconds per pass to minimise hypoxia, as suction removes oxygen along with secretions.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 5, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient in the ICU develops urinary retention as a postoperative complication. Which intervention should the nurse implement to address this issue?', '["Insert a urinary catheter", "Encourage the patient to drink plenty of fluids", "Encourage frequent ambulation", "Administer diuretic medications"]'::jsonb, 0, 'Inserting a urinary catheter provides immediate bladder decompression when a patient cannot void postoperatively.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 6, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient is on the AC volume ventilation after open heart surgery, which of the following is to be taken care of during this mode to pneumothorax?', '["delivering low PEEP", "keeping the patient sedated", "patient effort to breath more comfortable", "high peak inspiratory pressure"]'::jsonb, 3, 'A high peak inspiratory pressure is the warning sign of barotrauma/pneumothorax risk.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 7, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient with heart failure and severe hyponatremia (Na⁺ 115 mEq/L) develops seizures. Which intervention should the nurse initiate FIRST?', '["Start oral sodium chloride tablets", "Restrict oral fluid intake to 500 mL/day", "Give furosemide 40 mg IV", "Administer 3% hypertonic saline IV"]'::jsonb, 3, 'Severe symptomatic hyponatremia (e.g., seizures) requires rapid correction with 3% hypertonic saline to prevent cerebral edema and herniation. Fluid restriction and diuretics are adjunctive but not immediate for life-threatening symptoms.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 8, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A postoperative ICU patient is at risk for developing urinary retention. What nursing interventions can help prevent urinary retention?', '["Inserting a catheter", "Encouraging ambulation", "Limiting fluid intake", "Providing a bedside commode"]'::jsonb, 1, 'Ambulation promotes normal bladder emptying and reduces urinary retention risk in postoperative ICU patients.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 9, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Addisonian (adrenal) crisis typically presents with:', '["High glucose with weight gain and striae", "Hypotension, low Na⁺, high K⁺ and low glucose", "High sodium with polyuria and thirst", "Hypertension with low potassium and alkalosis"]'::jsonb, 1, 'Treat with IV hydrocortisone 100 mg, fluids and glucose.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 10, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Sildenafil is used in pulmonary arterial hypertension because it:', '["Inhibits phosphodiesterase-5, increasing NO-mediated vasodilation", "Acts as a potent loop diuretic that reduces right ventricular preload", "Acts as a beta-blocker that slows the heart and reduces RV workload", "Blocks endothelin receptors on the pulmonary vascular smooth muscle"]'::jsonb, 0, 'Bosentan is the endothelin antagonist. Nitrates must not be given with sildenafil because of severe hypotension.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 11, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'In critical care, what is the primary role of a diuretic medication?', '["A) Elevating blood pressure", "B) Increasing heart rate", "D) Reducing oxygen levels", "C) Promoting urine output"]'::jsonb, 3, 'Diuretics work primarily by promoting urine output.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 12, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'The most important early treatment priority in severe acute pancreatitis is:', '["Strict fasting for 2 weeks", "Prophylactic antibiotics in all cases", "Goal-directed IV fluid resuscitation", "Early surgery to remove the pancreas"]'::jsonb, 2, 'Fluids prevent hypovolaemia and necrosis. Early enteral feeding is preferred to TPN.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 13, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A urinary sodium below 20 mmol/L in oliguria suggests:', '["Recent loop diuretic administration", "Pre-renal AKI with intact tubules", "Established acute tubular necrosis", "Post-renal obstruction of the outflow"]'::jsonb, 1, 'ATN causes urinary sodium above 40 mmol/L.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 14, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'When is the use of spironolactone possibly contraindicated?', '["When also prescribing furosemide", "In hyperkalaemia patients", "In patients with refractory congestive heart failure", "In hypernatremia patients"]'::jsonb, 1, 'Spironolactone (a potassium-sparing diuretic) risks dangerous hyperkalaemia, so it is used cautiously in that setting.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 15, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Nephrotoxic drugs to avoid in AKI include:', '["Paracetamol in normal therapeutic doses", "Insulin given by continuous infusion", "Oxygen given by face mask or cannula", "Aminoglycosides, NSAIDs, IV contrast"]'::jsonb, 3, 'Doses of renally cleared drugs are adjusted.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 16, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A 30 years old male admitted to ICU with RTA (road traffic accident), she is unconscious and is on ventilator with Tidal volume=550 and FiO2=90%. She has CVP line inserted because of failure to insert I/V cannula, IV bolus of 1 litre and blood was infused. You are measuring his CVP which is 12cm of H2O, what does this indicate?', '["Normal volume", "Hypovolemia", "Hypervolemia", "Mixed state"]'::jsonb, 2, 'CVP of 12 (above the normal 2-8 range) indicates volume overload — hypervolaemia.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 17, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'What is the preferred treatment for anaphylactic shock?', '["Epinephrine", "Place the patient in sitting position and administer oxygen", "Prevent the infection from occurring through patient teaching", "Place a bag of ice on the area"]'::jsonb, 0, 'Epinephrine is the first-line, life-saving treatment for anaphylaxis.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 18, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'The following electrolyte is most found outside the cells .', '["Magnesium", "Potassium", "Bicarbonate", "Sodium"]'::jsonb, 3, 'Sodium is the predominant extracellular cation.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 19, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient''s urine output in PACU is 10 mL/h for 2 hours after major surgery (70 kg). The nurse should:', '["Give a diuretic straight away to increase the output, without assessment", "Remove the catheter and wait for the patient to void", "Check the catheter, assess fluid status and inform the doctor", "Do nothing, as this output is normal after major surgery"]'::jsonb, 2, 'Target is at least 0.5 mL/kg/h (35 mL/h here).', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 20, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A postoperative patient with hypocalcemia (ionized Ca²⁺ 0.8 mmol/L) exhibits carpopedal spasm and laryngeal stridor. Which action takes priority?', '["Administer oral calcium carbonate", "Infuse 10% calcium gluconate IV", "Apply a nasal cannula at 2 L/min", "Give vitamin D supplements"]'::jsonb, 1, 'IV calcium gluconate is critical for acute, symptomatic hypocalcemia to reverse neuromuscular irritability and prevent respiratory arrest.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 21, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'The method used during Exchange blood transfusion procedure is', '["PUSH", "PUSH-PULL", "PULL", "PULL-PUSH"]'::jsonb, 3, 'The push-pull technique describes how blood is exchanged during an exchange blood transfusion.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 22, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which of the following postoperative complications involves the abnormal accumulation of fluid at the surgical site?', '["Seroma", "Adhesion formation", "Paralytic ileus", "Urinary retention"]'::jsonb, 0, 'A seroma is a localised collection of serous fluid at the surgical site.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 23, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Over-insertion of the guidewire during central line placement risks causing:', '["No clinical consequence", "Arrhythmias", "Improved cardiac function", "Immediate cure of the underlying condition"]'::jsonb, 1, 'If the wire is advanced too far, it can irritate the heart''s conduction system and trigger an arrhythmia.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 24, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Pulse pressure variation above 13% in a ventilated patient suggests:', '["The patient is likely to be fluid responsive", "The arterial line trace is damped", "The patient is already fluid overloaded", "Cardiac tamponade is developing"]'::jsonb, 0, 'It is valid only in sinus rhythm with controlled ventilation.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 25, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Oliguria in an adult is generally defined as urine output less than:', '["5 mL/kg/hr", "10 mL/kg/hr", "0.5 mL/kg/hr", "3 mL/kg/hr"]'::jsonb, 2, 'Oliguria is typically defined as urine output under 0.5 mL/kg/hr, a key clinical indicator of reduced renal perfusion or function.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 26, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'During the cooling phase of induced hypothermia, the nurse should monitor closely for:', '["Polycythaemia, hypercalcaemia and hypernatraemia", "Tachycardia, high potassium and low blood glucose", "Bradycardia, low potassium, high glucose, coagulopathy", "Hypertension with a shortened bleeding time only"]'::jsonb, 2, 'Cold shifts potassium into cells; rewarming shifts it out, risking hyperkalaemia.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 27, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Removal of only 30–50 mL of blood during pericardiocentesis in tamponade typically produces:', '["Immediate cardiac arrest", "No change because more is needed", "Marked improvement in blood pressure", "Worsening of hypotension"]'::jsonb, 2, 'The pericardial pressure-volume curve is steep, so small volumes matter.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 28, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Rubbing frozen tissue during frostbite management is:', '["Recommended to restore circulation", "Only done if pain-free", "Never done — it worsens tissue damage", "Only done on the hands"]'::jsonb, 2, 'Ice crystals inside and around the cells make the tissue extremely fragile; rubbing causes further mechanical damage.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 29, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'This disease condition consists of train of severe seizures with relatively short intervals or no interval between, the patient becomes exhausted and frequently hyperthermia. Death not uncommonly occurs during the attacks.', '["Persistent convulsion", "Meningeal irritation", "Status epilepticus", "Poor epilepsy"]'::jsonb, 0, 'Continuous seizures with exhaustion and hyperthermia describe status epilepticus.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 30, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient''s urine output is measured at 20ml over the last hour, with a weight of 70kg. This represents a urine output of approximately:', '["No clinical significance regardless of the value", "5ml/kg/hr, indicating polyuria", "0.3ml/kg/hr, consistent with oliguria requiring assessment", "2ml/kg/hr, a normal finding"]'::jsonb, 2, '20ml/hr ÷ 70kg ≈ 0.29ml/kg/hr, below the generally accepted minimum of 0.5ml/kg/hr, indicating oliguria requiring prompt assessment.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 31, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Percussion, as an airway clearance technique, is applied:', '["During both inspiration and expiration", "During expiration only", "During inspiration only", "Only while the patient is standing"]'::jsonb, 0, 'Unlike vibration, percussion with cupped hands is applied throughout the whole breathing cycle.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 32, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'During pericardiocentesis, the ECG shows ST elevation and ventricular ectopics. This suggests:', '["The needle is touching the myocardium and must be withdrawn", "A normal response to the injected local anaesthetic", "The effusion has been successfully and fully drained", "The tamponade has resolved and the heart is refilling"]'::jsonb, 0, 'Myocardial contact causes injury current and arrhythmias; the needle is pulled back.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 33, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'In a fully ventilated patient in sinus rhythm, pulse pressure variation above 13% suggests:', '["The patient is already fluid overloaded", "The patient is likely to respond to a fluid bolus", "The arterial line trace is over-damped", "Severe left ventricular systolic failure"]'::jsonb, 1, 'PPV is only reliable with controlled ventilation, VT about 8 mL/kg and a regular rhythm.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 34, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Hyperkalaemia with ECG changes is first treated with:', '["Oral potassium binders as the only treatment", "IV calcium gluconate 10% to protect the heart", "IV potassium chloride to correct the ECG", "IV furosemide alone to excrete potassium"]'::jsonb, 1, 'Then insulin with dextrose and salbutamol shift potassium into cells.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 35, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient aspirates acidic gastric contents during an emergency intubation. Within hours, the most likely picture is:', '["A unilateral pleural effusion with a shift of the trachea", "Wheeze, hypoxaemia and bilateral infiltrates (chemical pneumonitis)", "Lobar consolidation with a high fever within the first hour", "A normal chest X-ray with no respiratory symptoms at all"]'::jsonb, 1, 'Mendelson''s syndrome is chemical; bacterial pneumonia may follow later.', 'NNP 417 · Medical-Surgical Nephrology I'),
(1, 36, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Vasoconstrictors (e.g. adrenaline) added to local anaesthetics are contraindicated in:', '["Spinal anaesthesia", "Epidural anaesthesia", "Regional anaesthesia", "Digital nerve block"]'::jsonb, 3, 'Adrenaline-containing local anaesthetics are avoided in digital (finger/toe), penile and similar end-artery blocks because of the risk of ischaemia.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 37, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'The Nurse define diabetes mellitus to his patient as chronic ---------characterized by elevated levels of blood glucose, which leads over time to serious damage to the heart, blood vessels, eyes, kidneys and nerves.', '["Metabolic disease", "Endocrine disease", "Gastrointestinal disease", "Circulatory disease"]'::jsonb, 0, 'Diabetes mellitus is classified as a chronic metabolic disease.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 38, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Abnormal extension (decerebrate posturing) corresponds to which motor score on the Glasgow Coma Scale?', '["5", "3", "2", "4"]'::jsonb, 2, 'Decerebrate (abnormal extensor) posturing is scored as a motor response of 2, indicating more severe brainstem dysfunction than decorticate (flexor) posturing (score 3).', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 39, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'An infected obstructed kidney requires:', '["Analgesia only, with a repeat scan in the clinic in 6 weeks", "Urgent drainage by nephrostomy or stent plus antibiotics", "Elective shock-wave lithotripsy booked in about 3 months", "Oral fluids and waiting for the stone to pass on its own"]'::jsonb, 1, 'Obstruction with infection can lead quickly to urosepsis and death.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 40, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A patient with end-stage renal disease has a serum K⁺ of 6.8 mEq/L and ECG shows widened QRS complexes. Which intervention is MOST urgent?', '["Give calcium gluconate 10% IV", "Administer sodium polystyrene sulfonate orally", "Initiate hemodialysis", "Infuse 10 units of regular insulin IV with 50% dextrose"]'::jsonb, 0, 'Calcium gluconate stabilizes cardiac membranes to prevent arrhythmias from hyperkalemia. Insulin/dextrose shifts K⁺ intracellularly but does not address imminent cardiac risk. Dialysis is definitive but slower.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 41, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A double-J (JJ) ureteric stent:', '["Drains urine from the bladder to the skin", "Keeps the ureter open from kidney to bladder", "Is a type of urinary catheter in the urethra", "Replaces the urethra"]'::jsonb, 1, 'Patients must know when it is due for removal.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 42, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A urine sample for culture from a catheter should be taken:', '["By disconnecting the bag", "From the drainage bag tap after it has been emptied", "From the drainage bag", "From the sampling port using aseptic technique"]'::jsonb, 3, 'Bag urine is contaminated.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 43, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'After radical cystectomy with ileal conduit, mucus in the urostomy bag is:', '["Normal, from the bowel segment", "A sign of cancer recurrence", "Always a sign of infection needing antibiotics", "A sign of kidney failure"]'::jsonb, 0, 'Encourage good fluid intake.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 44, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'The nurse is assessing a patient with a UWSD for a hemothorax. The nurse knows that the UWSD is primarily used to:', '["Provide a pathway for medication administration", "Drain air from the pleural space", "Drain blood and fluid from the pleural space", "Provide oxygen to the patient"]'::jsonb, 2, 'While UWSD can also drain air, its primary purpose in a hemothorax is to drain the accumulated blood and fluid from the pleural space, allowing the lung to re-expand and preventing complications.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 45, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Which gas is used to inflate balloon during diastole in Intra-aortic Balloon pump (IABP) machine?', '["Iodine", "Hydrogen", "Chlorine", "Helium"]'::jsonb, 3, 'Helium is used because its low viscosity allows very rapid balloon inflation/deflation, and it''s safer if it embolises.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 46, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A 70 kg man after a crash has pulse 125, BP 95/70, RR 32, urine 10 mL/hour and is anxious and confused. Using the ATLS classes, his estimated blood loss is:', '["Class IV, over 2000 mL (over 40%)", "Class I, under 750 mL (under 15%)", "Class III, 1500–2000 mL (30–40%)", "Class II, 750–1500 mL (15–30%)"]'::jsonb, 2, 'Class III shows a falling systolic BP, tachycardia above 120, low urine output and confusion. It requires blood transfusion.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 47, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A long-term effect commonly discussed with men before TURP is:', '["Diabetes and weight gain", "Retrograde ejaculation", "Blindness", "Hearing loss"]'::jsonb, 1, 'Semen passes back into the bladder.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 48, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'The 4-2-1 rule for calculating maintenance IV fluid rate is based primarily on the patient''s:', '["Diagnosis only", "Blood pressure only", "Age only", "Body weight"]'::jsonb, 3, 'The 4-2-1 rule calculates maintenance fluid rate based on body weight in kilograms: 4ml/kg/hr for the first 10kg, 2ml/kg/hr for the next 10kg, and 1ml/kg/hr for each kg thereafter.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 49, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Early ECG changes of hyperkalaemia typically include:', '["Flattened T waves", "Prolonged QT interval as the earliest change", "Tall, peaked T waves", "U waves"]'::jsonb, 2, 'Peaked, tented T waves are typically the earliest ECG change of hyperkalaemia, progressing to PR prolongation, widened QRS, and eventually a sine-wave pattern if untreated.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 50, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A patient s/p TURP has pink-tinged urine and bladder spasms. This is:', '["Indicative of infection", "Urinary retention", "Normal", "Sign of hemorrhage"]'::jsonb, 2, 'Hematuria and spasms are common after TURP.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 51, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Low potassium level is termed _____', '["Hyper-potassium syndrome", "Hypokalemia", "Hyperkalemia", "Hypo-potassiumaemia"]'::jsonb, 1, 'Low potassium is hypokalaemia.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 52, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Organ effects of abdominal compartment syndrome include:', '["Improved lung compliance and diuresis", "Polyuria, low airway pressures, high cardiac output", "Hypertension with increased venous return", "Oliguria, high airway pressures, low cardiac output"]'::jsonb, 3, 'Raised IAP compresses the kidneys and IVC and pushes the diaphragm up.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 53, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'The usual first priority when aspiration of gastric content is witnessed during induction is:', '["Sit the patient upright and give oral fluids to wash the throat", "Wait for a chest X-ray before doing anything else", "Give IV steroids as the first and most important step", "Head-down tilt, suction and a cuffed tube to secure the airway"]'::jsonb, 3, 'Bronchoscopy may be needed for particulate matter; antibiotics are not routine for chemical pneumonitis.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 54, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A 24 year old male is presented to ER with head injury. The patient has Tracheostomy intact. Heart Rate is below 50/min.Physician advised to administer Atropine 1 mg immediately. The only route of administering medication is Trachea now. Along with Atropine what other medications can be administered through Trachea;', '["NaHCO3", "Calcium", "Amiodarone,", "Adrenaline"]'::jsonb, 3, 'Endotracheal drugs follow "NAVEL" — adrenaline (epinephrine) can be given via the ET route along with atropine.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 55, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'After a head injury, urine output rises to 400 mL/h with low urine specific gravity and serum Na⁺ 152 mmol/L. The nurse suspects:', '["SIADH; expect fluid restriction", "Cerebral salt wasting; expect hypertonic saline", "Diabetes insipidus; expect desmopressin", "Acute tubular necrosis; expect dialysis"]'::jsonb, 2, 'Replace losses and check sodium closely.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 56, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'An ICU patient develops signs of delirium postoperatively. What nursing interventions are appropriate for managing delirium?', '["Encouraging fluid intake", "Ensuring a quiet environment", "Limiting communication with the patient", "Administering sedatives"]'::jsonb, 1, 'A calm, quiet, and appropriately oriented environment reduces sensory overload that can worsen postoperative delirium.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 57, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Which of the following conditions is associated with hyponatremia?', '["A. Diuretic therapy", "C. Diabetes insipidus", "B. Cushing''s syndrome", "D. Nephrotic syndrome"]'::jsonb, 0, 'Diuretic therapy is a recognised cause of hyponatraemia through sodium loss.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 58, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'The cosyntropin (synacthen) stimulation test assesses:', '["Insulin secretion by the pancreas", "Adrenal cortisol response to ACTH", "Growth hormone release", "Thyroid hormone production"]'::jsonb, 1, 'A poor rise in cortisol suggests adrenal insufficiency.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 59, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A patient has measured Na⁺ 128 mmol/L with blood glucose 40 mmol/L (720 mg/dL). The corrected sodium is about:', '["143 mmol/L", "160 mmol/L", "128 mmol/L", "118 mmol/L"]'::jsonb, 0, 'Add about 2.4 mmol/L of Na⁺ for every 5.5 mmol/L (100 mg/dL) of glucose above normal: 128 + 2.4 × 6.2 ≈ 143.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 60, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'The ''prehn sign'' (pain relieved by lifting the testis) is more suggestive of:', '["Epididymitis than testicular torsion", "Testicular torsion", "Hydrocele with fluid around the testis", "Varicocele"]'::jsonb, 0, 'It is not reliable enough to exclude torsion.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 61, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Dehydration is suggested by:', '["Bradycardia with peripheral oedema and weight gain", "Polyuria with very dilute urine and low urea", "Raised JVP with basal crackles and a gallop", "Tachycardia, dry mucosa, oliguria, raised urea"]'::jsonb, 3, 'Urea rises more than creatinine in pre-renal states.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 62, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Hypocalcaemia in severe pancreatitis is caused by:', '["Hyperparathyroidism from pancreatic damage", "Retention of calcium by the kidneys", "Excess calcium absorption from the gut", "Saponification of calcium in fat necrosis"]'::jsonb, 3, 'Calcium below 2 mmol/L is a poor prognostic sign; watch for tetany and arrhythmias.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 63, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A bladder scan in an ICU patient with a urinary catheter showing 450 mL suggests:', '["Catheter blockage or malposition", "Normal residual volume in a catheterised patient", "Acute kidney injury with oliguria", "Over-hydration requiring diuretics"]'::jsonb, 0, 'A catheterised bladder should be nearly empty. Check for kinks, clots or a balloon in the urethra.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 64, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Bipolar TURP using normal saline irrigation reduces the risk of:', '["Retrograde ejaculation", "Infection of the prostate bed after surgery", "TURP syndrome from hyponatraemia", "Bleeding completely"]'::jsonb, 2, 'Monopolar TURP requires non-conductive glycine.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 65, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Insulin should not be started in DKA until the potassium is at least:', '["2.0 mmol/L", "6.5 mmol/L", "5.5 mmol/L", "3.3 mmol/L"]'::jsonb, 3, 'Insulin drives potassium into cells; starting it with hypokalaemia can cause fatal arrhythmias.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 66, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'The preferred muscle relaxant in a patient with liver or renal failure is:', '["Pancuronium", "Atracurium", "Rocuronium", "Vecuronium"]'::jsonb, 1, 'Atracurium (and cisatracurium) is broken down by Hofmann elimination and ester hydrolysis, without needing the liver or kidneys.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 67, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A patient vomits blood-stained fluid in PACU after nasal surgery. This is most likely:', '["Swallowed blood from the operative site", "Upper GI cancer bleeding", "A sign of severe hypoglycaemia after fasting", "Normal bile from the stomach"]'::jsonb, 0, 'Monitor for ongoing bleeding from the nose.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 68, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'During CPR, the recommended compression-to-ventilation ratio for a single rescuer performing adult CPR without an advanced airway is:', '["30:2", "15:2", "5:1", "Continuous compressions with no ventilation"]'::jsonb, 0, 'For a single rescuer without an advanced airway, the standard adult CPR ratio is 30 compressions to 2 rescue breaths.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 69, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Percussion during airway clearance techniques is performed using:', '["A closed fist", "Mechanical hammers only", "Cupped hands", "Flat, open-palm slapping"]'::jsonb, 2, 'Cupping the hands traps a cushion of air that transmits a rhythmic vibration into the chest wall without causing direct pain from a flat strike.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 70, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'The volume of blood in the ventricles just before they contract. It denotes the overall fluid status of the body.', '["After load", "Cardiac Output", "Contractility", "Preload"]'::jsonb, 3, 'Preload is the ventricular volume just before contraction.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 71, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Which of the following common ICU-acquired pathogens is a fungal organism (rather than bacterial)?', '["Klebsiella pneumoniae", "Pseudomonas aeruginosa", "MRSA", "Candida species"]'::jsonb, 3, 'Candida species are fungal organisms and a recognised cause of ICU-acquired infections, particularly in patients with central lines or broad-spectrum antibiotic exposure.', 'NNP 412 · Applied Biochemistry'),
(1, 72, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'The life span of sickled red blood cells is about:', '["90 days", "60 days", "20 days", "120 days"]'::jsonb, 2, 'Sickled red cells are rigid and are destroyed early, surviving only about 10–20 days compared with 120 days for normal red cells.', 'NNP 412 · Applied Biochemistry'),
(1, 73, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'An ABG analysis report shows: pH - 7.30; PCO2 - 35mmHg; HCO3- -18mEq/L. These findings are suggestive of', '["Metabolic acidosis", "Respiratory acidosis", "Respiratory alkalosis", "Metabolic alkalosis"]'::jsonb, 0, 'Low pH with normal PCO2 and low HCO3 points to a metabolic (not respiratory) acidosis.', 'NNP 412 · Applied Biochemistry'),
(1, 74, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Which of these genotypes is most susceptible to severe malaria?', '["AA (normal homozygote)", "SC", "SS", "AS (sickle-cell trait)"]'::jsonb, 0, 'People with normal haemoglobin (HbAA) lack the partial protection against severe falciparum malaria that sickle trait (HbAS) gives.', 'NNP 412 · Applied Biochemistry'),
(1, 75, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'What is the primary purpose of administering potassium chloride infusion to patient with diabetic ketoacidosis recieving IV insulin?', '["Treatment of hypepnea", "Prevention of fluccid paralysis", "Treatment of cardiac arrythmias", "Replacement of potassium losses"]'::jsonb, 3, 'Insulin drives potassium into cells, so KCl is given to replace/prevent depletion of total body potassium.', 'NNP 412 · Applied Biochemistry'),
(1, 76, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Troponin is considered a highly specific biomarker for:', '["Myocardial injury", "Hepatic injury", "Renal injury", "Pancreatic injury"]'::jsonb, 0, 'Cardiac troponin (I or T) is released specifically from injured cardiac myocytes, making it a highly sensitive and specific biomarker for myocardial injury.', 'NNP 412 · Applied Biochemistry'),
(1, 77, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A client is receiving a blood transfusion. The critical care nurse observes that the client is experiencing diarrhoea, abdominal pain, and chills. Which of the following actions should the nurse take FIRST?', '["Get a warming blanket.", "Assist the client to the bathroom.", "Administer meperidine.", "Stop the transfusion."]'::jsonb, 3, 'Diarrhoea, pain, and chills during a transfusion signal a reaction — stopping the transfusion is the first priority action.', 'NNP 412 · Applied Biochemistry'),
(1, 78, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'For a patient on warfarin therapy, the therapeutic INR target for most indications is typically:', '["8.0–10.0", "2.0–3.0", "0.5–1.0", "5.0–6.0"]'::jsonb, 1, 'Most indications for warfarin (e.g. atrial fibrillation, DVT/PE treatment) target an INR of 2.0–3.0; mechanical heart valves may require a higher target range.', 'NNP 412 · Applied Biochemistry'),
(1, 79, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'ABG: pH 7.20, PaCO₂ 25 mmHg, HCO₃⁻ 10 mmol/L indicates:', '["Metabolic alkalosis with respiratory compensation", "Mixed respiratory and metabolic alkalosis", "Acute respiratory acidosis without compensation", "Metabolic acidosis with respiratory compensation"]'::jsonb, 3, 'Expected PaCO₂ = 1.5 × HCO₃⁻ + 8 (±2) = 23 mmHg.', 'NNP 412 · Applied Biochemistry'),
(1, 80, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Platelets should not be given through:', '["A central line", "A peripheral cannula", "A used blood giving set", "A platelet or new standard giving set"]'::jsonb, 2, 'Use a fresh set to avoid platelet loss.', 'NNP 412 · Applied Biochemistry'),
(1, 81, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A low reticulocyte count in anaemia indicates:', '["Acute bleeding with good marrow", "Reduced bone marrow production", "Increased red cell destruction", "Haemolysis"]'::jsonb, 1, 'High reticulocytes suggest haemolysis or bleeding.', 'NNP 412 · Applied Biochemistry'),
(1, 82, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Which person should be deferred if the event happened within the previous 24 hours?', '["A person who had a cholesterol check", "A person who drank alcohol", "A person who ate breakfast", "A person who slept 8 hours"]'::jsonb, 1, 'Anyone who has drunk alcohol in the previous 24 hours should not donate blood.', 'NNP 412 · Applied Biochemistry'),
(1, 83, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'The ABGs of a ventilated patient showed that PH= 7.25, PCO2 = 55 mm HG and HCO3= 25 MEq/L. As a nurse what changes would you suggest in the Ventilator settings?', '["Decrease Respiratory Rate", "Decreasing Tidal Volume 36- Disease is a response to (A)Specific infective agents (", "Increase FiO2", "Increase Respiratory Rate"]'::jsonb, 3, 'A low pH with high PCO2 (uncompensated respiratory acidosis) is corrected by increasing the respiratory rate to blow off more CO2.', 'NNP 412 · Applied Biochemistry'),
(1, 84, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Elevated ALT and AST primarily indicate:', '["Coagulopathy directly", "Renal dysfunction", "Hepatocellular injury", "Pancreatic dysfunction only"]'::jsonb, 2, 'ALT and AST are intracellular liver enzymes released into the blood when hepatocytes are injured, making them markers of hepatocellular damage.', 'NNP 412 · Applied Biochemistry'),
(1, 85, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'In a patient with pulmonary arterial hypertension, which factor most worsens pulmonary vascular resistance and must be avoided in the ICU?', '["Hypoxia, hypercapnia and acidosis", "A slightly alkalotic pH from mild hyperventilation", "Mild hyperoxia with normocapnia", "Normothermia with adequate analgesia"]'::jsonb, 0, 'Hypoxia, hypercarbia and acidosis cause pulmonary vasoconstriction. Oxygen, normocapnia and avoiding acidosis lower PVR.', 'NNP 412 · Applied Biochemistry'),
(1, 86, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Which test measures the concentration of hydrogen ions in the blood and is essential for assessing acid-base balance?', '["Urinalysis", "Blood urea nitrogen (BUN)", "Serum creatinine", "Blood pH"]'::jsonb, 3, 'Blood pH is a critical measure of acid-base balance, which can be affected by', 'NNP 412 · Applied Biochemistry'),
(1, 87, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'ABG: pH 7.48, PaCO₂ 48 mmHg, HCO₃⁻ 35 mmol/L indicates:', '["Respiratory acidosis with metabolic compensation", "Metabolic acidosis with respiratory compensation", "Metabolic alkalosis with respiratory compensation", "Acute respiratory alkalosis from hyperventilation"]'::jsonb, 2, 'Causes include vomiting, NG suction and diuretics.', 'NNP 412 · Applied Biochemistry'),
(1, 88, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Raised serum lactate after cardiac arrest mainly reflects:', '["Excess dietary lactate given in the enteral feed", "Hyperventilation by the team during CPR", "Tissue hypoperfusion and anaerobic metabolism", "Liver overproduction of glucose after adrenaline"]'::jsonb, 2, 'Clearance of lactate suggests improving perfusion.', 'NNP 412 · Applied Biochemistry'),
(1, 89, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A patient was rushed to the clinic department due to hyperventilation. Which nursing intervention is the most appropriate for the client who is subsequently developing respiratory alkalosis?', '["Administering sodium chloride I.V.", "Administer low-flow oxygen therapy.", "Encouraging slow, deep breaths.", "Preparing to administer sodium bicarbonate."]'::jsonb, 2, 'Slow, deep breathing helps a hyperventilating patient retain CO2 and correct respiratory alkalosis.', 'NNP 412 · Applied Biochemistry'),
(1, 90, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A patient with diabetic ketoacidosis has K⁺ 5.2 mEq/L before insulin therapy. After starting insulin, which K⁺ level indicates effective treatment?', '["3.2 mEq/L", "4.8 mEq/L", "3.9 mEq/L", "5.0 mEq/L"]'::jsonb, 0, 'Insulin drives K⁺ into cells, causing hypokalemia. A drop to 3.2 mEq/L reflects successful intracellular shift but requires replacement to prevent arrhythmias.', 'NNP 412 · Applied Biochemistry'),
(1, 91, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Most of the carbon dioxide in the Blood is transported as?', '["solute dissolved in the Blood", "Bicarbonate ion", "carbonic acid", "carbonmonohemoglobin"]'::jsonb, 1, 'Most CO2 in the blood is transported as bicarbonate ion.', 'NNP 412 · Applied Biochemistry'),
(1, 92, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'The first step in the recommended 5-step ABG interpretation approach is to assess:', '["Base excess only", "Oxygenation", "Compensation", "Anion gap"]'::jsonb, 1, 'Checking oxygenation (PaO2/SO2) first ensures you don''t miss a life-threatening hypoxaemia while focused on acid-base status.', 'NNP 412 · Applied Biochemistry'),
(1, 93, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Which laboratory result would the nurse expect in DIC?', '["An increased white cell count", "A low fibrinogen level", "A decreased prothrombin time (PT)", "An increased platelet count"]'::jsonb, 1, 'DIC consumes fibrinogen and platelets, so fibrinogen is low, platelets are low, PT/aPTT are prolonged and D-dimer is raised.', 'NNP 412 · Applied Biochemistry'),
(1, 94, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A nurse is caring for a post- CABG patient. While performing hemodynamic monitoring, he noted that Pulmonary Artery pressure is 31/18. The nurse would understand which of the following abnormality as the cause of the this PA pressure reading:', '["Right sided heart failure", "Pulmonary infection", "Pulmonary valve stenosis", "Left side heart failure"]'::jsonb, 3, 'Elevated pulmonary artery pressures often reflect back-pressure transmitted from a failing left heart.', 'NNP 412 · Applied Biochemistry'),
(1, 95, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Which is true about haemophilia C?', '["It is due to factor VIII deficiency", "It is known as Christmas disease", "It is due to factor XI deficiency", "It is due to factor IX deficiency"]'::jsonb, 2, 'Haemophilia A is factor VIII deficiency, B (Christmas disease) is factor IX, and C is factor XI deficiency.', 'NNP 412 · Applied Biochemistry'),
(1, 96, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A patient came to the ER with Difficulty in breathing; He was intubated and placed on Mechanical ventilation. His ABGs report showed that his PCO2 is 55 mm Hg. To wash out CO2 which of the following parameter(s) should be adjusted:', '["Vt and PEEP", "Vt and R/R", "PEEP and FiO2", "Fio2 and R/R"]'::jsonb, 1, 'Washing out CO2 means increasing minute ventilation — adjusting tidal volume and respiratory rate.', 'NNP 412 · Applied Biochemistry'),
(1, 97, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Culture and sensitivity results guide:', '["Antibiotic choice and de-escalation", "Blood group selection for transfusion", "The choice of IV maintenance fluid", "Sedation dosing in ventilated patients"]'::jsonb, 0, 'Empirical therapy is changed once results return.', 'NNP 412 · Applied Biochemistry'),
(1, 98, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'The LEAST important part of initial DKA treatment is:', '["Giving sodium bicarbonate", "Giving fluids", "Giving potassium chloride", "Lowering blood glucose with insulin"]'::jsonb, 0, 'Bicarbonate is rarely needed in DKA (only if pH <6.9). Fluids, insulin and potassium come first.', 'NNP 412 · Applied Biochemistry'),
(1, 99, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'The normal anion gap range is:', '["100–150mmol/L", "8–18mmol/L", "0–5mmol/L", "30–50mmol/L"]'::jsonb, 1, 'Values above this range suggest a high-anion-gap metabolic acidosis, caused by extra unmeasured acid in the blood.', 'NNP 412 · Applied Biochemistry'),
(1, 100, 'Nephrology Nursing Mock — Day 7 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Radial artery sampling for ABG is typically performed at what needle angle?', '["10°", "180°", "45°", "90°"]'::jsonb, 2, 'A 45° angle, bevel up, is the standard technique for accessing the relatively superficial radial artery.', 'NNP 412 · Applied Biochemistry'),
(2, 1, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Post-operative pain in toddlers is best assessed using:', '["Asking them to rate pain 0–10", "A behavioural tool such as FLACC", "Measuring blood glucose", "Checking pupil size and blood pressure only"]'::jsonb, 1, 'Older children can use faces scales.', 'NNP 423 · Paediatric Nephrology'),
(2, 2, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Biliary atresia should be treated by the Kasai procedure ideally before:', '["60 days of age", "10 years of age", "Puberty", "2 years of age"]'::jsonb, 0, 'Persistent jaundice beyond 2 weeks with pale stools must be investigated.', 'NNP 423 · Paediatric Nephrology'),
(2, 3, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A child with suspected Lassa fever is admitted. The nurse''s first priority is:', '["Relatives providing care freely at the bedside", "Isolation only after results return", "Admission to an open paediatric ward", "Strict isolation with full PPE"]'::jsonb, 3, 'Health worker infection is common; sharps and body fluids are handled with extreme care.', 'NNP 423 · Paediatric Nephrology'),
(2, 4, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Which action best prevents heat loss by evaporation in a newborn?', '["Turning on the overhead radiant warmer", "Closing the doors to the room", "Warming the crib pad", "Drying the infant with a warm blanket"]'::jsonb, 3, 'Evaporative heat loss comes from wet skin. Drying the baby immediately with a warm towel prevents it.', 'NNP 423 · Paediatric Nephrology'),
(2, 5, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Oxygen saturation targets of about 91–95% in preterm infants help prevent:', '["Umbilical cord infection", "Neonatal hypoglycaemia", "Retinopathy of prematurity", "Physiological neonatal jaundice"]'::jsonb, 2, 'Both too much and too little oxygen cause harm.', 'NNP 423 · Paediatric Nephrology'),
(2, 6, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Respiratory distress syndrome in a 28-week preterm baby is mainly due to:', '["Surfactant deficiency", "Meconium aspiration", "Excess surfactant", "Congenital heart disease"]'::jsonb, 0, 'Treat with antenatal steroids, CPAP and surfactant via the tube.', 'NNP 423 · Paediatric Nephrology'),
(2, 7, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A nurse is performing neonatal resuscitation. The newborn''s heart rate is below 60 beats per minute after 30 seconds of effective positive-pressure ventilation. The next step is to:', '["Administer epinephrine", "Initiate chest compressions", "Continue positive-pressure ventilation for another 30 seconds", "Stop resuscitation and call the physician"]'::jsonb, 1, 'According to NALS guidelines, if the heart rate remains below 60 beats per minute after 30 seconds of effective positive-pressure ventilation, the nurse should initiate chest compressions while continuing ventilation. Epinephrine is administered if the heart rate remains below 60 bpm after another 60 seconds of chest compressions and ventilation.', 'NNP 423 · Paediatric Nephrology'),
(2, 8, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'The following anomalies except one occur due to malformation of the renal parenchyma. Which is the exception?', '["Renal tubular dysgenesis", "Dysplastic kidneys", "Polycystic kidney disease", "Posterior urethral valves"]'::jsonb, 3, 'The correct answer is: Posterior urethral valves.', 'NNP 423 · Paediatric Nephrology'),
(2, 9, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Early-onset neonatal sepsis (within 72 hours) is most commonly caused by:', '["Pseudomonas from ventilators", "Staphylococcus epidermidis from lines", "Candida albicans", "Group B Streptococcus and E. coli"]'::jsonb, 3, 'Late-onset sepsis is often hospital-acquired, e.g. coagulase-negative staphylococci.', 'NNP 423 · Paediatric Nephrology'),
(2, 10, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A nurse is providing care for a newborn who is at risk for hypothermia. The most effective nursing intervention is to:', '["Place the newborn under a radiant warmer", "Keep the newborn''s crib away from any heat sources", "Bathe the newborn immediately after birth", "Wrap the newborn in a cold towel"]'::jsonb, 0, 'Placing the newborn under a radiant warmer is the most effective way to prevent and treat hypothermia. It provides a constant source of heat that helps to maintain the newborn''s body temperature. Bathing should be delayed until the temperature is stable.', 'NNP 423 · Paediatric Nephrology'),
(2, 11, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A baby with congenital diaphragmatic hernia at birth should NOT receive:', '["A nasogastric tube to decompress the stomach", "Prolonged bag-and-mask ventilation", "Intubation and gentle ventilation", "Warmth and monitoring"]'::jsonb, 1, 'Mask ventilation fills the bowel in the chest and worsens breathing.', 'NNP 423 · Paediatric Nephrology'),
(2, 12, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Meckel''s diverticulum classically presents in children with:', '["Jaundice with pale stools", "Haematuria", "Painless rectal bleeding", "Projectile vomiting"]'::jsonb, 2, 'Remember the ''rule of 2s'': 2% of people, 2 feet from the ileocaecal valve.', 'NNP 423 · Paediatric Nephrology'),
(2, 13, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'The maximum allowable blood loss calculation in children helps the team to:', '["Know when to give blood during surgery", "Calculate the fasting time needed before surgery", "Decide the theatre temperature", "Choose the instruments"]'::jsonb, 0, 'It is based on estimated blood volume and starting haematocrit.', 'NNP 423 · Paediatric Nephrology'),
(2, 14, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Blue colour, Moderate tone, Inadequate breath and Slow heart rate in a neonate should be followed by which action', '["Commence active resuscitation", "Wrap baby and handover to mother", "Keep baby in the cot", "Commence breastfeeding"]'::jsonb, 0, 'Blue colour, poor tone, inadequate breathing, and slow heart rate mean the neonate needs active resuscitation.', 'NNP 423 · Paediatric Nephrology'),
(2, 15, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A 35year old para 7+2 [6alive] ,just had a spontaneous vaginal delivery of a live baby boy, she is lying on bed not talking, on examination her pulse rate is 100b/m, blood pressure 50/?, the possible cause is: ___________', '["Thromboembolism", "Inadequate history of onset of labor", "Inadequate history during antenatal booking", "Not regular in antenatal visit prenatally"]'::jsonb, 0, 'Persistent hypotension/tachycardia postpartum with unclear labour history raises suspicion for occult bleeding tied to inadequate labour monitoring/history.', 'NNP 423 · Paediatric Nephrology'),
(2, 16, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Caffeine citrate is used in preterm babies to:', '["Prevent neonatal hypoglycaemia", "Treat apnoea of prematurity", "Treat neonatal jaundice", "Sedate the restless baby"]'::jsonb, 1, 'It is given once daily; tachycardia and feed intolerance are side effects.', 'NNP 423 · Paediatric Nephrology'),
(2, 17, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A child with perforated appendicitis develops fever and abdominal distension 5 days after surgery. The nurse should suspect:', '["Paralytic ileus without infection", "Normal post-operative course", "Urinary tract infection only", "Pelvic or intra-abdominal abscess"]'::jsonb, 3, 'Persistent fever with pain suggests abscess; ultrasound or CT is needed.', 'NNP 423 · Paediatric Nephrology'),
(2, 18, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A child''s short trachea means that an endotracheal tube can easily:', '["Fall out with head extension only", "Move into a main bronchus with head flexion", "Never move, as children''s tubes are always cuffed", "Enter the oesophagus on its own"]'::jsonb, 1, 'Secure the tube well and check after each move.', 'NNP 423 · Paediatric Nephrology'),
(2, 19, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'The purpose of performing an EBT in a severely jaundiced baby is to urgently reduce the blood level of unconjugated bilirubin so as to prevent', '["Unconjugated bilirubin", "Febrile illness", "Brain damage", "Asphyxia"]'::jsonb, 2, 'Rapidly lowering unconjugated bilirubin via EBT prevents kernicterus (brain damage).', 'NNP 423 · Paediatric Nephrology'),
(2, 20, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Incarcerated inguinal hernia in paediatrics is treated by', '["Anti-inflammatory", "Antibiotics", "Analgesics", "Emergency surgery"]'::jsonb, 3, 'An incarcerated hernia is a surgical emergency requiring urgent operative repair.', 'NNP 423 · Paediatric Nephrology'),
(2, 21, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Undescended testis (cryptorchidism) is usually corrected by orchidopexy at:', '["6–12 months, before about 2 years", "At puberty, when the testis enlarges", "At birth only, before the first feed", "In adulthood, when fertility is tested"]'::jsonb, 0, 'Early surgery reduces risk of infertility and makes testicular cancer easier to detect.', 'NNP 423 · Paediatric Nephrology'),
(2, 22, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A child with a severe asthma attack not responding to salbutamol may need:', '["Oral sedation and discharge home", "IV magnesium sulphate and oxygen", "Strict fluid restriction for 24 hours", "Oral antibiotics and nothing else"]'::jsonb, 1, 'Aminophylline and ventilation may follow.', 'NNP 423 · Paediatric Nephrology'),
(2, 23, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Meconium ileus in a newborn is strongly associated with:', '["Cystic fibrosis", "Sickle cell disease", "Down syndrome", "Hypothyroidism"]'::jsonb, 0, 'Thick meconium blocks the ileum.', 'NNP 423 · Paediatric Nephrology'),
(2, 24, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A congenital hydrocele in an infant usually:', '["Means a testicular tumour", "Needs immediate drainage", "Causes kidney failure if not drained at once", "Resolves by about 1–2 years of age"]'::jsonb, 3, 'Surgery is done if it persists or a hernia is present.', 'NNP 423 · Paediatric Nephrology'),
(2, 25, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Most umbilical hernias in infants:', '["Close on their own by about 4–5 years", "Strangulate in the first week", "Turn cancerous if they are not removed early", "Need emergency surgery"]'::jsonb, 0, 'Surgery is offered if they persist or are large.', 'NNP 423 · Paediatric Nephrology'),
(2, 26, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Gastroschisis differs from exomphalos in that gastroschisis:', '["Is always covered by a membrane of amnion and peritoneum", "Is strongly linked with trisomies and cardiac defects", "Contains the liver and bowel within a thin covering sac", "Has bowel outside beside the umbilicus with no covering sac"]'::jsonb, 3, 'Exposed bowel is wrapped in cling film to reduce heat and fluid loss, the baby is nursed on the side, and IV fluids are started.', 'NNP 423 · Paediatric Nephrology'),
(2, 27, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'The most effective way to reduce neonatal infection in a special care baby unit is:', '["Bathing every baby twice a day with antiseptic", "Routine prophylactic antibiotics for all babies", "Keeping the mothers out of the unit completely", "Hand hygiene before and after every baby contact"]'::jsonb, 3, 'Breast milk and kangaroo care also reduce infection.', 'NNP 423 · Paediatric Nephrology'),
(2, 28, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A child with HIV and severe pneumonia should receive:', '["Oral fluids only, with close observation", "Oral paracetamol only, given at home", "Oxygen, antibiotics and high-dose cotrimoxazole", "Steroids alone, without any antibiotics"]'::jsonb, 2, 'Prednisolone is added for moderate-severe PCP.', 'NNP 423 · Paediatric Nephrology'),
(2, 29, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A baby is brought in apnoeic and pulseless at home. The nurse should:', '["Give oxygen by mask and observe", "Wait for the doctor to confirm death", "Ask the parents what happened first", "Start paediatric CPR and call the team"]'::jsonb, 3, 'Infants receive 15:2 compressions to breaths with two rescuers.', 'NNP 423 · Paediatric Nephrology'),
(2, 30, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Puerperal pyrexia is defined as a temperature of 38 °C or above:', '["Within 14 days after childbirth or miscarriage", "Only in the first hour after delivery", "Only during the first stage of labour", "Only after the 6-week postnatal check"]'::jsonb, 0, 'It requires investigation for infection, including the genital tract, breast and urine.', 'NNP 423 · Paediatric Nephrology'),
(2, 31, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Severe neonatal hypothermia increases the risk of:', '["Hypertension and polyuria", "Hyperglycaemia and metabolic alkalosis", "Increased surfactant production", "Hypoglycaemia, acidosis and respiratory distress"]'::jsonb, 3, 'Cold stress increases oxygen use and brown fat metabolism.', 'NNP 423 · Paediatric Nephrology'),
(2, 32, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'After cleft palate repair, the child''s arms may be restrained with elbow splints to:', '["Prevent fractures of the arms on waking", "Prevent the child from crying after feeds", "Stop fingers and objects damaging the repair", "Encourage the child to sleep after surgery"]'::jsonb, 2, 'Feeding is by cup or spoon as advised; straws and teats may be avoided. Suction near the repair is avoided.', 'NNP 423 · Paediatric Nephrology'),
(2, 33, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A child with sickle cell disease and sudden severe anaemia with a rapidly enlarging spleen has:', '["Acute splenic sequestration crisis", "Aplastic crisis from parvovirus", "Haemolytic crisis from malaria", "Vaso-occlusive bone crisis"]'::jsonb, 0, 'It can cause shock and death; urgent transfusion is needed.', 'NNP 423 · Paediatric Nephrology'),
(2, 34, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Appendicitis in a child under 5 is more dangerous because:', '["The pain is always well localised in them", "Young children always present very early", "Appendicitis never occurs below this age", "Early perforation; the omentum is poorly developed"]'::jsonb, 3, 'Generalised peritonitis is common at presentation.', 'NNP 423 · Paediatric Nephrology'),
(2, 35, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Children with HIV in ICU commonly present with:', '["Kidney stones and renal colic", "Hypertension and haemorrhagic stroke", "Severe pneumonia, including Pneumocystis", "Gallstones and acute cholecystitis"]'::jsonb, 2, 'PCP is treated with high-dose cotrimoxazole and steroids.', 'NNP 423 · Paediatric Nephrology'),
(2, 36, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'A molar pregnancy (hydatidiform mole) typically shows:', '["Very high hCG and a ''snowstorm'' pattern on ultrasound", "A normal placenta", "No hCG at all in the blood, with a normal-looking fetus", "Low hCG and a normal fetus"]'::jsonb, 0, 'Treatment is suction evacuation with hCG follow-up.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 37, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Management of uterine rupture is one of the following', '["Uterine relaxation with tocolytic", "oxytocin should be administered", "Taking of history", "Simple repair"]'::jsonb, 3, 'Simple surgical repair is the standard management approach for uterine rupture.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 38, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Bimanual uterine compression is used to:', '["Close the cervix after delivery of the placenta", "Deliver the placenta", "Control haemorrhage from uterine atony", "Turn a breech baby"]'::jsonb, 2, 'Combine with uterotonic drugs while preparing for theatre.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 39, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'In normal foetal growth hypertrophy and hyperplasia occurs within............gestation', '["20 to 24 weeks", "22 to 24 weeks", "20 to 28 weeks", "16 to 32 weeks"]'::jsonb, 3, 'Foetal hypertrophy/hyperplasia growth phases occur across roughly 16-32 weeks gestation.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 40, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Which statement about intussusception is FALSE?', '["It usually occurs in healthy babies without a demonstrable cause", "It most commonly occurs at the ileocolic junction", "It is mostly found in adolescents", "The proximal bowel telescopes into the distal bowel"]'::jsonb, 2, 'Intussusception is most common in infants of 6–18 months, usually ileocolic and often without a clear cause. It is not mainly an adolescent disease.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 41, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Primary postpartum haemorrhage is defined as blood loss of:', '["500 mL or more between 6 and 12 weeks later", "100 mL or more within 24 h of vaginal birth", "50 mL or more within the first hour of birth", "500 mL or more within 24 h of vaginal birth"]'::jsonb, 3, 'For caesarean section, 1000 mL or more is often used. Secondary PPH occurs between 24 hours and 12 weeks.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 42, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'During exchange transfusion, blood is removed and replaced in small aliquots mainly to:', '["Avoid sudden swings in blood volume", "Allow more bilirubin to be removed", "Speed up the whole procedure", "Reduce the amount of donor blood used"]'::jsonb, 0, 'Aliquots of 5–20 mL depending on weight are used.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 43, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'After vaginal hysterectomy, the nurse should monitor for:', '["Hearing loss", "Wrist pain and swelling from the IV cannula", "Facial swelling", "Vaginal bleeding and urinary retention"]'::jsonb, 3, 'A vaginal pack and catheter may be in place.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 44, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'This describe a woman who has never been pregnant before.', '["Multigravida", "Nulligravida", "Primipara", "Primipgravida"]'::jsonb, 1, 'A woman who has never been pregnant is a nulligravida.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 45, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'After evacuation of a molar pregnancy, the woman is advised to:', '["Avoid pregnancy until hCG follow-up is complete", "Become pregnant immediately", "Stop all contraception and try to conceive again straight away", "Have a hysterectomy in all cases"]'::jsonb, 0, 'Rising hCG may mean gestational trophoblastic neoplasia.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 46, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'A missed miscarriage means:', '["The pregnancy is outside the uterus", "The cervix opened with heavy bleeding", "The fetus has died but has not been passed", "All the products of conception have been passed completely"]'::jsonb, 2, 'Options include medical or surgical evacuation.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 47, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'One of the following is a prevention of cervical incompetence', '["Not having regular check-up during pregnancy", "Seeking regular parental care", "Smoking", "Weight gain"]'::jsonb, 1, 'Regular antenatal care helps detect and manage cervical incompetence early.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 48, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'A pregnant patient at 32 weeks presents with painless, bright red vaginal bleeding. This presentation is most concerning for:', '["Placenta praevia", "Round ligament pain", "Normal spotting in pregnancy", "Placental abruption"]'::jsonb, 0, 'Painless bright red bleeding in later pregnancy is classic for placenta praevia, whereas placental abruption typically presents with painful bleeding.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 49, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Physiological jaundice differs from pathological jaundice because physiological jaundice:', '["Appears within the first 24 hours", "Requires exchange transfusion in all cases", "Appears after 24 hours and resolves by 2 weeks", "Is associated with a conjugated bilirubin rise"]'::jsonb, 2, 'Jaundice in the first 24 hours is always pathological.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 50, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Indomethacin may reduce polyhydramnios by:', '["Increasing fetal swallowing", "Reducing fetal urine production", "Increasing maternal urine output", "Causing uterine contractions"]'::jsonb, 1, 'It can cause premature closure of the fetal ductus arteriosus, so use is limited.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 51, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Which is true about breastfeeding and contraception?', '["An IUCD can be inserted just after delivery", "Breastfeeding remains effective even with regular formula top-ups", "All oral contraceptives are contraindicated", "Breastfeeding is highly effective once menses return"]'::jsonb, 0, 'A postplacental IUCD (within 10 minutes of placental delivery) is safe and suits breastfeeding women. Progestin-only methods are also fine.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 52, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Primary postpartum haemorrhage following a caesarean section is defined as blood loss of:', '["≥500ml", "≥1000ml", "≥250ml", "≥3000ml"]'::jsonb, 1, 'The threshold is higher after a C-section (1000ml) compared to a vaginal delivery (500ml), reflecting the naturally greater blood loss expected with surgery.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 53, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'A trial of labour after one previous lower segment caesarean section carries a small risk of:', '["Placenta praevia in that labour", "Uterine rupture", "Hyperemesis", "Rh disease"]'::jsonb, 1, 'Continuous fetal monitoring is advised.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 54, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Hypotension after spinal anaesthesia for caesarean section is best treated with:', '["Head-up tilt to 45 degrees with the legs down", "Phenylephrine infusion with fluid co-loading", "Withholding all IV fluids to avoid oedema", "Large doses of IV furosemide and fluid restriction"]'::jsonb, 1, 'Phenylephrine maintains BP without fetal acidosis; ephedrine is an alternative.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 55, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'In 80 percent of women, the long axis of uterus lies at the right angle to the long axis of the vagina with a forward tilt. It is called:', '["Retroflexion", "Retroversion", "Anteversion", "Anteflexion"]'::jsonb, 2, 'The correct answer is: Anteversion.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 56, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'The final surgical option for life-threatening postpartum haemorrhage when other measures fail is:', '["Myomectomy", "Hysterectomy", "Cervical cerclage", "Tubal ligation only"]'::jsonb, 1, 'Earlier steps include balloon tamponade, B-Lynch and vessel ligation.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 57, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Normal physiologic and anatomical changes occurring in pregnancy occurs naturally and are termed:', '["Natural tolerance", "Natural adaptations", "Anatomical adaptations and tolerance", "Physiological adaptation and tolerance"]'::jsonb, 1, 'The correct answer is: Natural adaptations.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 58, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Hysterectomy that removes the uterus and cervix is called:', '["Oophorectomy", "Subtotal hysterectomy", "Myomectomy", "Total hysterectomy"]'::jsonb, 3, 'Subtotal leaves the cervix. Radical hysterectomy (Wertheim''s) includes parametrium, upper vagina and pelvic lymph nodes.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 59, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'The main cause of cervical cancer is persistent infection with:', '["Human papillomavirus (HPV)", "Candida albicans (thrush) infection", "Herpes simplex virus", "Hepatitis B virus"]'::jsonb, 0, 'HPV vaccination and screening prevent most cases.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 60, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Other than transfusion, when is it necessary to take the Rh Factor into consideration?', '["Pregnancy", "Spleen Rupture", "Blood Donation", "Cathertization"]'::jsonb, 0, 'Rh factor compatibility is critical in pregnancy due to risk of maternal-fetal Rh incompatibility.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 61, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'An acute event involving the cardiorespiratory and/or central nervous system that causes reduced or absent consciousness in pregnancy is:', '["Hyperemesis gravidarum", "Maternal collapse", "Ectopic pregnancy", "Placenta praevia"]'::jsonb, 1, 'Maternal collapse is an acute cardiorespiratory and/or CNS event causing reduced or absent consciousness, at any stage of pregnancy up to 6 weeks after delivery.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 62, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Which one of these treatments of leukemia is still under investigation?', '["Bone marrow transplant", "Immunotherapy", "Gene therapy", "Cord blood and placenta transplant"]'::jsonb, 2, 'Gene therapy for leukaemia remains an area of ongoing investigation/research rather than standard established treatment.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 63, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'A woman with a uterine scar (previous caesarean) and severe abdominal pain with fetal heart abnormalities in labour suggests:', '["False labour", "Normal labour pain", "Uterine rupture", "Urinary tract infection"]'::jsonb, 2, 'Immediate laparotomy is needed.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 64, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'According to the Thomas-Kilmann model, the conflict resolution style with both high assertiveness and high cooperation is:', '["Avoiding", "Competing", "Collaborating", "Accommodating"]'::jsonb, 2, 'Collaborating aims for a genuine win-win outcome, requiring both parties to actively push for and cooperate toward a shared solution.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 65, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'ACE inhibitors are contraindicated in pregnancy-related hypertension mainly because they can cause:', '["Maternal hair loss", "No significant risk", "Improved placental blood flow", "Fetal renal toxicity"]'::jsonb, 3, 'These drugs can damage the developing fetal kidneys, making them unsafe throughout pregnancy.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 66, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Bartholin''s cyst recurrence is reduced by:', '["Ice packs", "Simple needle aspiration only", "Antibiotic cream alone", "Marsupialisation"]'::jsonb, 3, 'This creates a permanent opening for drainage.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 67, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Vacuum (ventouse) delivery is contraindicated in:', '["A term baby in occipito-anterior position", "A fully dilated cervix", "A preterm baby under about 34 weeks", "Maternal exhaustion"]'::jsonb, 2, 'Preterm babies are at greater risk of scalp and brain injury.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 68, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'During hysteroscopy with fluid distension, the nurse records fluid input and output because of the risk of:', '["Fluid overload and hyponatraemia", "Hypothermia only", "Hypoglycaemia from the glucose in the fluid", "Hypertension only"]'::jsonb, 0, 'Stop if the fluid deficit exceeds the safe limit.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 69, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Tranexamic acid in postpartum haemorrhage should be given:', '["Only after hysterectomy", "Only after 24 hours", "Within 3 hours of birth", "Only if the patient is not bleeding"]'::jsonb, 2, 'The WOMAN trial showed reduced deaths from bleeding.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 70, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Bilateral tubal ligation is a:', '["Temporary, reversible contraceptive", "Treatment for tubal infertility", "Permanent method of sterilisation", "Method of inducing labour at term"]'::jsonb, 2, 'Informed consent must stress permanence. It can be done at caesarean section or laparoscopically.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 71, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'The specific antidote for opioid overdose (e.g. morphine, fentanyl) is:', '["Activated charcoal", "N-acetylcysteine", "Flumazenil", "Naloxone"]'::jsonb, 3, 'Naloxone is a competitive opioid receptor antagonist used to reverse opioid-induced respiratory depression.', 'NNP 413 · Applied Pharmacology'),
(2, 72, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Specific antidote in paracetamol poisoning is', '["Activated charcoal", "Acetyl cysteine", "Naloxone", "Desferroxamine"]'::jsonb, 1, 'Acetylcysteine is the specific antidote for paracetamol overdose.', 'NNP 413 · Applied Pharmacology'),
(2, 73, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Protamine sulphate is given to:', '["Reverse the effect of aspirin", "Reverse the effect of heparin", "Treat insulin-induced hypoglycaemia", "Reverse the effect of warfarin"]'::jsonb, 1, 'Protamine binds heparin. It is given slowly to avoid hypotension and anaphylactoid reactions, especially in patients with fish allergy or previous protamine-containing insulin use.', 'NNP 413 · Applied Pharmacology'),
(2, 74, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Clinically significant carbon monoxide production within an anaesthesia circuit is most associated with which agent reacting with desiccated (dried-out) CO2 absorbent?', '["Oxygen alone", "Propofol", "Desflurane", "Sevoflurane"]'::jsonb, 2, 'Desflurane (and to a lesser extent isoflurane) can react with desiccated absorbent, particularly older barium hydroxide lime, to generate carbon monoxide; keeping absorbent adequately hydrated and changed regularly minimizes this risk.', 'NNP 413 · Applied Pharmacology'),
(2, 75, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Benzylpenicillin is the chemical name for:', '["Penicillin F", "Penicillin G", "Phenethicillin", "Penicillin V"]'::jsonb, 1, 'Benzylpenicillin is penicillin G. Penicillin V is phenoxymethylpenicillin.', 'NNP 413 · Applied Pharmacology'),
(2, 76, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Ipratropium bromide is used in the management of:', '["Acute asthmatic attack", "Acute peptic ulcer disease", "Acute bronchopneumonia", "Acute gastroenteritis"]'::jsonb, 0, 'Ipratropium bromide is an inhaled anticholinergic bronchodilator, added to salbutamol in acute severe asthma and used in COPD.', 'NNP 413 · Applied Pharmacology'),
(2, 77, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'which of this is a narcotic analgesics', '[".Morphine", "Halothen", "Ibuprofen", "Acetamophine"]'::jsonb, 0, 'Morphine is a classic narcotic (opioid) analgesic.', 'NNP 413 · Applied Pharmacology'),
(2, 78, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Excessive anticoagulation with bleeding due to warfarin can be reversed by:', '["Diuretics", "Vitamin K", "Protamine sulphate", "Aspirin"]'::jsonb, 1, 'Warfarin is reversed with vitamin K (phytomenadione), plus prothrombin complex concentrate or FFP for major bleeding.', 'NNP 413 · Applied Pharmacology'),
(2, 79, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient on a β-blocker has hypoglycemia. Which sign may be masked?', '["Tachycardia", "Diaphoresis", "Tremors", "Hunger"]'::jsonb, 0, 'β-blockers blunt tachycardia (adrenergic response) in hypoglycemia.', 'NNP 413 · Applied Pharmacology'),
(2, 80, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Atropine is used in anaesthesia to:', '["Induce sleep at the start of anaesthesia", "Treat bradycardia and dry secretions", "Raise the blood glucose before surgery", "Reverse opioid respiratory depression"]'::jsonb, 1, 'Atropine is an anticholinergic (muscarinic blocker). Side effects include dry mouth, tachycardia, urinary retention, blurred vision and confusion in the elderly.', 'NNP 413 · Applied Pharmacology'),
(2, 81, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'The specific reversal agent for unfractionated heparin is:', '["Dantrolene", "Fresh frozen plasma only", "Protamine sulfate", "Vitamin K"]'::jsonb, 2, 'Protamine sulfate binds and neutralises heparin, providing rapid reversal of its anticoagulant effect.', 'NNP 413 · Applied Pharmacology'),
(2, 82, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'The nurse is caring for a patient who is on a continuous infusion of Propofol. The nurse should be aware that the infusion should be changed every:', '["24 hours", "12 hours", "48 hours", "72 hours"]'::jsonb, 1, 'Propofol is a lipid-based medication, which makes it a perfect medium for bacterial growth. The infusion and tubing must be changed every 12 hours to reduce the risk of a bloodstream infection.', 'NNP 413 · Applied Pharmacology'),
(2, 83, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Ondansetron is used perioperatively as:', '["A dopamine-blocking antihypertensive", "A 5-HT3 antagonist antiemetic", "A short-acting muscle relaxant", "A sedative premedication"]'::jsonb, 1, 'Ondansetron is effective for postoperative nausea and vomiting. It may cause headache, constipation and QT prolongation.', 'NNP 413 · Applied Pharmacology'),
(2, 84, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'An early sign of malignant hyperthermia under anaesthesia is:', '["A falling body temperature", "A fall in heart rate and blood pressure", "Pinpoint pupils", "An unexplained rise in end-tidal CO₂"]'::jsonb, 3, 'Stop triggering agents, give dantrolene 2.5 mg/kg IV and cool the patient.', 'NNP 413 · Applied Pharmacology'),
(2, 85, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient is admitted to ICU with diagnosis of vaso-occlusive crisis, which of this management will you start with?', '["Order for narcotics and administer", "Transfuse with fresh whole blood", "Rehydrate with normal saline", "Give oral rehydration solution"]'::jsonb, 2, 'Aggressive rehydration with normal saline is the first step in managing vaso-occlusive crisis.', 'NNP 413 · Applied Pharmacology'),
(2, 86, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Paracetamol overdose is dangerous because it causes:', '["Respiratory alkalosis", "Acute pancreatitis", "Liver failure", "Kidney stones"]'::jsonb, 2, 'Toxic metabolite NAPQI depletes glutathione. N-acetylcysteine is the antidote. Adult maximum dose is 4 g per 24 hours, less in low body weight or liver disease.', 'NNP 413 · Applied Pharmacology'),
(2, 87, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'When titrating sedation in a mechanically ventilated ICU patient, the nurse should primarily use:', '["A validated sedation scale (e.g. RASS) to guide titration", "No formal scale — sedation should be maximised at all times", "The patient''s family''s preference alone", "Blood pressure alone as the only guide"]'::jsonb, 0, 'Validated sedation scales such as the Richmond Agitation-Sedation Scale (RASS) guide safe titration, avoiding both under- and over-sedation.', 'NNP 413 · Applied Pharmacology'),
(2, 88, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'The pharmacy needs 500 mL of a 5% dextrose solution but only has 50% dextrose stock solution and sterile water available. How much of the 50% stock solution is needed?', '["250 mL of stock, diluted with 250 mL water", "5 mL of stock, diluted with 495 mL water", "50 mL of stock, diluted with 450 mL water", "100 mL of stock, diluted with 400 mL water"]'::jsonb, 2, 'Using C1V1 = C2V2: 50% x V1 = 5% x 500 mL, so V1 = 2500/50 = 50 mL of stock, topped up with 450 mL diluent to make 500 mL.', 'NNP 413 · Applied Pharmacology'),
(2, 89, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Flushing and rash on the upper body during IV vancomycin is best managed by:', '["Giving it as an IV push", "Slowing the infusion rate", "Doubling the dose", "Stopping all antibiotics permanently"]'::jsonb, 1, 'This ''red man'' reaction is histamine release, not true allergy. Also monitor levels and kidney function.', 'NNP 413 · Applied Pharmacology'),
(2, 90, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'The drugs which are used during Basic Life Support (BLS):', '["Atropine and Amiodarone", "Epinephrine and Amiodarone", "Epinephrine and Vasopressin", "Atropine and Epinephrine"]'::jsonb, 1, 'Epinephrine and amiodarone are the standard ACLS arrest drugs referenced here.', 'NNP 413 · Applied Pharmacology'),
(2, 91, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Prophylactic antibiotics given before surgery are ideally administered:', '["Within about 60 minutes before surgical incision", "Only if the patient develops a fever post-operatively", "More than 6 hours before incision", "Only after the wound is closed"]'::jsonb, 0, 'Surgical antibiotic prophylaxis is most effective when given within roughly 60 minutes before incision, ensuring adequate tissue levels at the time of surgery.', 'NNP 413 · Applied Pharmacology'),
(2, 92, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Which drug is effective in treating oral candidiasis?', '["Tetracycline", "Nystatin", "Bacitracin", "Griseofulvin"]'::jsonb, 1, 'Nystatin is a polyene antifungal used topically and orally for oral candidiasis (thrush).', 'NNP 413 · Applied Pharmacology'),
(2, 93, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Convert 500 milligrams to grams', '["0.5ng", "0.5mg", "0.5g", "0.05g"]'::jsonb, 2, '500mg = 0.5g (dividing by 1000 to convert mg to g).', 'NNP 413 · Applied Pharmacology'),
(2, 94, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Naloxone is administered to a patient in the Emergency room. This is an antidote for for which of the following type of poisoning?', '["Alcohol overdose", "Tricyclic antidepressant use", "Chlorine poisoning", "Opiate poisoning"]'::jsonb, 3, 'Naloxone is the specific opioid antagonist/antidote.', 'NNP 413 · Applied Pharmacology'),
(2, 95, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'To provide rapid pain relief in the ICU, which of the following routes of opioid administration is most appropriate?', '["Intraspinal", "Intradermal", "Sublingual", "Intravenous"]'::jsonb, 3, 'IV opioids act within minutes and can be titrated, which makes IV the route for rapid pain relief in ICU.', 'NNP 413 · Applied Pharmacology'),
(2, 96, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient with septic shock is started on vasopressin. Which effect is expected?', '["Decreased SVR", "Increased urine output", "Vasoconstriction", "Coronary vasodilation"]'::jsonb, 2, 'Vasopressin is a potent vasoconstrictor used in refractory septic shock.', 'NNP 413 · Applied Pharmacology'),
(2, 97, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'In emergency treatment of impending anaphylaxis from a drug, which action comes FIRST among these?', '["Inserting an I.V. catheter.", "Taking vital signs.", "Obtaining a Full blood count (FBC).", "Administering oxygen."]'::jsonb, 3, 'In anaphylaxis, secure the airway and oxygenation first, then give IM adrenaline and get IV access.', 'NNP 413 · Applied Pharmacology'),
(2, 98, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Compound A, a potentially nephrotoxic breakdown product identified in animal studies, forms when which agent is used with low fresh gas flows and desiccated CO2 absorbent?', '["Nitrous oxide", "Isoflurane", "Sevoflurane", "Desflurane"]'::jsonb, 2, 'Sevoflurane degrades in contact with CO2 absorbents (particularly desiccated ones) to form Compound A, which has raised nephrotoxicity concerns at high concentrations and low fresh gas flows.', 'NNP 413 · Applied Pharmacology'),
(2, 99, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient on long-term diuretic therapy develops muscle weakness, cramping, and an irregular pulse. The nurse should suspect an electrolyte disturbance, most likely:', '["Hypokalaemia", "Hypercalcaemia", "Hyperglycaemia", "Hypernatraemia"]'::jsonb, 0, 'Muscle weakness, cramping and arrhythmia in a patient on diuretics (especially loop/thiazide) are classic signs of hypokalaemia, a common diuretic side effect.', 'NNP 413 · Applied Pharmacology'),
(2, 100, 'Nephrology Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'The second-line drug of choice for status epilepticus, given as an IV loading dose, is:', '["Salbutamol", "Adrenaline", "Lorazepam", "Phenytoin"]'::jsonb, 3, 'Phenytoin is used when first-line benzodiazepines alone haven''t stopped the seizure.', 'NNP 413 · Applied Pharmacology'),
(3, 1, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The most appropriate statements regarding the treatment of necrotizing soft tissue infections include:', '["Reconstructive surgery should be considered as emergency", "Intravenous immunoglobulin cannot bind to staphylococcal- and streptococcal-derived exotoxin.", "When methicillin resistant S. aureus (MRSA) is suspected, linezolid is preferred to vancomycin as it inhibits exotoxin production.", "The overall evidence for the mortality benefit of hyperbaric oxygen therapy is very effective, particularly for Clostridium spp."]'::jsonb, 0, 'Reconstructive/debridement surgery is treated as a surgical emergency in necrotizing soft tissue infection.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 2, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The confirmatory investigation for prostate cancer is:', '["Prostate scan", "PSA test", "Multiparametric MRI", "Prostate biopsy"]'::jsonb, 3, 'Prostate biopsy (histology) confirms prostate cancer. PSA and MRI guide suspicion.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 3, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'What percentage of mechanically ventilated patients develop significant weakness?', '["5%", "75%", "25%", "100%"]'::jsonb, 2, 'A meaningful proportion, roughly a quarter, of ventilated patients go on to develop significant weakness.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 4, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Early postoperative complication of thyroidectomy includes:', '["Tracheomalacia", "Keloid", "Hemorrhage", "Hypothyroidism"]'::jsonb, 2, 'Haemorrhage is a recognised early (not late) complication after thyroidectomy.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 5, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The chain of infection includes the agent, reservoir, portal of exit, mode of transmission, portal of entry and:', '["Clean environment", "Sterile equipment", "Healthy staff", "Susceptible host"]'::jsonb, 3, 'Breaking any link stops transmission.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 6, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Stretch of ventricular wall. Usually related to volume. (How full is the tank?)', '["Diastole", "Systolic pressure", "Afterload", "Preload"]'::jsonb, 3, 'Stretch of the ventricular wall related to filling volume is preload.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 7, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which of the following is the anticoagulant of choice for blood gas studies?', '["B. Lithium heparin", "D. Ammonium oxalate 5.0%", "C. Sodium citrate 3.8%", "A. Sodium citrate 3.2%"]'::jsonb, 0, 'Lithium heparin is the preferred anticoagulant for blood gas sampling.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 8, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A nurse is positioning an unconscious patient. The patient''s head should be maintained in a:', '["Hyperextended position", "Neutral, midline position", "Flexed position on the chest", "Rotated position to the side"]'::jsonb, 1, 'Maintaining the head in a neutral, midline position helps to ensure venous drainage from the head, which can help to prevent an increase in intracranial pressure. Any flexion or rotation can impede blood flow.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 9, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which of the following patients is most likely to be weaned from oxygen therapy?', '["A patient with a chronic obstructive pulmonary disease (COPD) exacerbation", "A patient with a PaO₂ of 95 mmHg on a nasal cannula at 2 L/min", "A patient with a SpO₂ of 88% on room air", "A patient with a PaO₂ of 60 mmHg on a non-rebreather mask"]'::jsonb, 1, 'Weaning from oxygen therapy is a gradual process. A PaO₂ of 95 mmHg is well within the normal range, indicating that the patient is maintaining adequate oxygenation on a low-flow oxygen setting and may be ready to be weaned or have their oxygen discontinued.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 10, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The ICP threshold that generally triggers treatment in severe traumatic brain injury is above:', '["10–15 mmHg", "5–10 mmHg", "40–45 mmHg", "20–22 mmHg"]'::jsonb, 3, 'Normal ICP is about 5–15 mmHg.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 11, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A polytrauma patient develops confusion, hypoxia and a petechial rash over the axillae 48 hours after femoral fracture. The likely diagnosis is:', '["Pulmonary thromboembolism", "Fat embolism syndrome", "Septic shock from wound infection", "Transfusion-related lung injury"]'::jsonb, 1, 'Fat globules from long-bone marrow cause respiratory, neurological and skin features. Early fracture fixation reduces risk.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 12, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which of the following conditions would indicate referral to cardio respiratory Therapist?', '["COPD", "Ebola", "Incomplete SCI", "DIC"]'::jsonb, 0, 'COPD is a classic condition warranting cardiorespiratory therapist referral.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 13, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A deep tendon reflex graded 4+ means:', '["Normal, as expected", "Sluggish and diminished", "Very brisk, with clonus", "Absent, even with reinforcement"]'::jsonb, 2, 'Grades: 0 absent, 1+ diminished, 2+ normal, 3+ brisk, 4+ clonus.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 14, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'For severe choking in a conscious adult, management alternates between:', '["Head-tilt chin-lift and jaw thrust", "10 chest compressions and rescue breaths", "5 back slaps and 5 abdominal thrusts", "Recovery position and CPR"]'::jsonb, 2, 'Alternating back slaps and abdominal thrusts gives two different mechanical ways to dislodge the obstruction.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 15, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which of the following is not the main goal of mechanical ventilation in the ICU?', '["Optimize patient comfort", "Decrease work of breathing", "Optimize exchange of carbon dioxide and oxygen", "Get them through surgery with less discomfort"]'::jsonb, 0, '"Getting through surgery" isn''t a described core ICU ventilation goal — comfort, gas exchange, and reduced work of breathing are.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 16, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'What is the primary purpose of a Swan-Ganz catheter in critical care?', '["Administering insulin", "Measuring intracranial pressure (ICP)", "Monitoring blood pressure", "Monitoring cardiac hemodynamics"]'::jsonb, 3, 'A Swan-Ganz (pulmonary artery) catheter is used to monitor cardiac hemodynamics.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 17, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'What is the normal value of CVP in Millimeter of water?', '["2-8 mm of H2o", "2-3 mm of H2o", "2-5 mm of H2o", "2-4 mm of H2o"]'::jsonb, 0, 'Normal CVP is commonly cited as about 2-8 (mmHg, approximated here in the given unit).', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 18, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'First drug used to treat bradycardia:', '["Amiodarone", "Deltacortil", "Epinephrine", "Atropine"]'::jsonb, 3, 'Atropine is the first drug given for symptomatic bradycardia.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 19, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which laboratory test is generally considered the most sensitive initial screening test for primary thyroid dysfunction?', '["Thyroglobulin", "Free T3", "Serum TSH", "Total T4"]'::jsonb, 2, 'Because of the logarithmic inverse relationship between free T4 and TSH, even small changes in thyroid hormone produce large, easily detectable changes in TSH, making it the most sensitive screening test for primary thyroid disease.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 20, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'What name is given to the mechanical contraction of the heart?', '["Diastole", "Depolarisation", "Repolarisation", "Systole"]'::jsonb, 3, 'Systole is the mechanical contraction phase of the heart. Depolarisation is the electrical event that triggers it.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 21, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A key nursing intervention to prevent line sepsis is:', '["Scrubbing the hub before every access", "Changing dressings only when they fall off", "Leaving three-way taps open and uncapped", "Reusing syringes on the same patient''s line"]'::jsonb, 0, 'Use 2% chlorhexidine in alcohol for 15 seconds.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 22, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which of the following is the appropriate nursing intervention for a patient with a terminal illness who is passing through the acceptance stage?', '["Explaining the patient what is being done", "Being around though not speaking", "Allowing the patient to cry", "Encouraging unrestricted visiting"]'::jsonb, 1, 'In acceptance, patients often want quiet companionship rather than active talk or intervention.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 23, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'For a 2-rescuer child (not infant) CPR, the compression-to-ventilation ratio is:', '["15:2", "5:1", "30:2", "30:1"]'::jsonb, 0, 'With 2 trained rescuers present for a child, the ratio changes to 15 compressions to 2 breaths, allowing more frequent ventilation for the smaller patient.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 24, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'An emergency tracheostomy involves:', '["A tube passed through the mouth and larynx", "A puncture through the cricothyroid cartilage", "A tube passed through the nose into the trachea", "A surgical incision into the trachea"]'::jsonb, 3, 'A tracheostomy is a surgical opening (incision) into the trachea. A cricothyroidotomy goes through the cricothyroid membrane.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 25, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which of the following is referred to as air in the pleural space', '["Pneumothorax", "Pyothorax", "Pulmonary oedema", "Haemothorax"]'::jsonb, 0, 'Air in the pleural space is pneumothorax.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 26, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Prone positioning in moderate–severe ARDS is recommended when PaO₂/FiO₂ is below 150 mmHg, for at least:', '["16 hours a day", "1 hour a day", "30 minutes after each meal", "4 hours a week"]'::jsonb, 0, 'Nursing care during proning: protect eyes, face and pressure areas, secure the tube and lines, and plan for emergency supination.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 27, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The following is a secondary abdominal compartment syndrome.', '["Pancreatitis", "Trauma", "Ascites", "Septic shock"]'::jsonb, 3, 'Septic shock (a non-abdominal originating cause) is a classic secondary cause of abdominal compartment syndrome.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 28, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The Vitamin essential for blood clotting is_____________', '["Vitamin A", "Vitamin K", "Vitamin C", "Vitamin B"]'::jsonb, 1, 'Vitamin K is essential for the clotting cascade.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 29, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A patient is receiving oxygen via a non-rebreather mask. The nurse notices the reservoir bag is completely deflating with each inspiration. The most appropriate nursing action is to:', '["Replace the mask with a simple face mask", "Loosen the mask to allow more room air to enter", "Increase the oxygen flow rate to the mask", "Clamp the oxygen tubing"]'::jsonb, 2, 'The reservoir bag of a non-rebreather mask should remain inflated on both inspiration and expiration to ensure a high FiO₂ is delivered. If it is deflating, the flow rate is too low and should be increased to maintain a high concentration of oxygen.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 30, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Isoniazid neuropathy is prevented by giving:', '["Vitamin K (phytomenadione)", "Ascorbic acid (vitamin C)", "Pyridoxine (vitamin B6)", "Folic acid (vitamin B9)"]'::jsonb, 2, 'This is important in TB patients in Nigeria.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 31, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Before arterial line insertion, the nurse prepares a transducer set flushed with:', '["5% dextrose pressurised to 50 mmHg", "Unpressurised sterile water for injection", "Heparin 25 000 units in 10 mL only", "Pressurised normal saline at 300 mmHg"]'::jsonb, 3, 'Dextrose can cause errors in blood glucose sampling.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 32, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A patient with tearing chest pain radiating to the back and unequal arm blood pressures most likely has:', '["Aortic dissection", "Pulmonary embolism", "Oesophageal spasm", "Acute pericarditis"]'::jsonb, 0, 'Thrombolysis is contraindicated. Heart rate and BP are lowered rapidly with IV beta-blockers.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 33, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The nurse is monitoring the drainage from a UWSD. The nurse should report which of the following findings to the physician immediately?', '["Intermittent bubbling in the water-seal chamber", "Clear, serous fluid", "The presence of a small amount of drainage", "A sudden increase of bloody drainage"]'::jsonb, 3, 'A sudden increase in the amount of bloody drainage, particularly if it is bright red, can be a sign of active bleeding in the chest cavity, which is a medical emergency. The other options are considered normal findings or can be addressed by the nurse.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 34, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The minimum vital capacity generally required for ventilator weaning readiness is:', '["10ml/kg predicted body weight", "1ml/kg", "50ml/kg", "Vital capacity is not assessed"]'::jsonb, 0, 'This threshold suggests the patient has enough respiratory reserve to breathe adequately once support is withdrawn.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 35, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The qSOFA criteria are respiratory rate ≥22/min, altered mentation and:', '["Temperature ≥38 °C", "Urine output ≤0.5 mL/kg/h", "Heart rate ≥90/min", "Systolic BP ≤100 mmHg"]'::jsonb, 3, 'Two or more positive criteria outside ICU signal higher risk of death.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 36, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'In adult DKA, the recommended fixed-rate IV insulin infusion is:', '["10 units/hour for every patient", "0.01 unit/kg/hour of long-acting insulin", "1 unit/kg/hour of soluble insulin", "0.1 unit/kg/hour of soluble insulin"]'::jsonb, 3, 'Add potassium to fluids once K⁺ is below 5.5 mmol/L and urine is passed.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 37, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'BiPAP for acute hypercapnic COPD exacerbation works mainly by:', '["EPAP alone delivers a high, fixed oxygen fraction to the patient", "IPAP boosts tidal volume to clear CO₂; EPAP splints the airways", "It removes the need for any arterial blood gas monitoring", "It sedates the patient so that the breathing rate falls"]'::jsonb, 1, 'Failure (worsening pH after 1–2 hours) indicates the need for intubation.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 38, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A patient with hypokalemia has U waves on ECG. Which drug increases the risk of this finding?', '["Spironolactone", "Metoprolol", "Furosemide", "Amlodipine"]'::jsonb, 2, 'Loop diuretics (e.g., furosemide) cause renal K⁺ loss. U waves are a hallmark of hypokalemia.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 39, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Emphysema on a chest X-ray typically shows:', '["Bilateral fluffy alveolar shadowing with large heart", "A single dense lobar consolidation with air bronchogram", "Hyperinflation, flat diaphragms and increased lucency", "Small lungs with raised diaphragms on both sides"]'::jsonb, 2, 'Patients may have bullae, which can rupture into a pneumothorax during positive pressure ventilation.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 40, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The VAP bundle includes head-of-bed elevation of:', '["5–10 degrees only", "90 degrees at all times", "30–45 degrees", "Flat (0 degrees) to rest the lungs"]'::jsonb, 2, 'Other elements: daily sedation hold and SBT, oral care with chlorhexidine, subglottic suction, DVT and ulcer prophylaxis.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 41, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which of these drugs is used as an antidote for paralytic agents', '["Atropine", "Neostigmin", "Adrenaline", "Atracurium"]'::jsonb, 1, 'Neostigmine reverses non-depolarising paralytic agents by increasing acetylcholine availability.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 42, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'When removing (doffing) PPE after caring for an isolated patient, the correct order is:', '["Gloves, goggles, gown, mask, hand hygiene", "Mask first, then gloves, then gown", "Gown first, followed immediately by mask with no hand hygiene between", "Hand hygiene only, with no specific PPE removal order"]'::jsonb, 0, 'PPE doffing removes the most contaminated items first: gloves, then goggles, then gown, then mask, with hand hygiene performed at the end (and often between steps).', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 43, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'MAP 65 mmHg, CVP 5 mmHg and cardiac output 6 L/min give an SVR of about:', '["1600 dyn·s/cm⁵, high, as in cardiogenic shock", "2400 dyn·s/cm⁵, high, as in hypovolaemia", "80 dyn·s/cm⁵, low, as in heart block", "800 dyn·s/cm⁵, low, as in distributive shock"]'::jsonb, 3, 'SVR = (MAP − CVP) × 80 ÷ CO = 60 × 80 ÷ 6 = 800. Normal is 800–1200.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 44, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which of the following is a crucial precaution a nurse must take when administering oxygen therapy?', '["Ensure the patient''s hands and face are moisturized with petroleum-based products.", "Avoid humidification to prevent the growth of bacteria in the water.", "Place ''No Smoking'' signs in the patient''s room and surrounding area.", "Allow the oxygen tank to be placed on its side to conserve space."]'::jsonb, 2, 'Oxygen is a highly combustible gas that accelerates burning, so fire safety precautions such as ''No Smoking'' signs are essential. Petroleum-based products are flammable, and tanks must be kept upright and secured. Humidification is necessary to prevent drying of mucous membranes.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 45, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Protein reintroduction in PSE patients is generally recommended at:', '["20–50g/day", "100–150g/day", "0–10g/day", "No restriction needed"]'::jsonb, 0, 'Protein is carefully reintroduced at a moderate level to balance nutritional needs against the risk of worsening ammonia production.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 46, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which part of the heart''s conduction system is known as the "gatekeeper"?', '["SA node", "Bundle of His", "AV node", "Gap junction"]'::jsonb, 2, 'The AV node is the "gatekeeper": it delays conduction so the ventricles can fill and limits how fast impulses reach the ventricles.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 47, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A major risk factor for prostate cancer is:', '["Systemic hypertension", "A diet rich in antioxidants", "Ethnicity (African descent)", "Wealthy background"]'::jsonb, 2, 'Major prostate cancer risk factors are age, family history and ethnicity (higher in men of African descent).', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 48, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Arranged from outermost to innermost, the correct order of the three meningeal layers surrounding the brain and spinal cord is', '["arachnoid mater, dura mater, pia mater", "pia mater, arachnoid mater, dura mater", "dura mater, pia mater, arachnoid mater", "dura mater, arachnoid mater, pia mater"]'::jsonb, 3, 'From outside in, the meninges are the dura mater (tough outer layer), arachnoid mater (middle, web-like layer), and pia mater (innermost, adheres directly to neural tissue).', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 49, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Two days after minor surgery, a patient has severe wound pain out of proportion to its appearance, rapidly spreading redness, dusky skin, crepitus and septic shock. The most important action is:', '["Warm compresses, elevation and simple analgesia, then observation", "Urgent surgical debridement plus broad-spectrum IV antibiotics", "Wait for blood culture results before starting any treatment", "Oral antibiotics, wound swab, and review in the clinic in 48 hours"]'::jsonb, 1, 'Necrotising fasciitis (often Group A Streptococcus or polymicrobial) spreads along fascial planes. Mortality falls with early radical debridement; antibiotics alone are not enough.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 50, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'What is the term for non-invasive ventilation that uses face or nasal masks?', '["Invasive ventilation", "Non-invasive ventilation", "Negative pressure ventilation", "Positive pressure ventilation"]'::jsonb, 1, 'Ventilation delivered via a face/nasal mask without an artificial airway is non-invasive ventilation.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 51, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Successful reperfusion after thrombolysis is suggested by:', '["New Q waves appear in the same leads within an hour", "Complete heart block develops with a slow ventricular rate", "Chest pain persists with steadily rising ST segments", "ST elevation falls by over 50% and the pain settles"]'::jsonb, 3, 'Reperfusion arrhythmias (e.g. accelerated idioventricular rhythm) may also occur.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 52, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Neurogenic shock after high cord injury presents with:', '["Hypotension with bradycardia and warm skin", "Hypotension with tachycardia and cold skin", "Normal blood pressure", "Hypertension with bradycardia"]'::jsonb, 0, 'Loss of sympathetic tone causes vasodilation; atropine and vasopressors may be needed.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 53, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The ''golden age'' of antibiotic discovery occurred during which period?', '["1980–2000", "2000–present", "1900–1920", "1940–1965"]'::jsonb, 3, 'Most major antibiotic classes still in use today were discovered during this productive mid-20th-century period.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 54, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Magnesium sulphate in acute severe asthma is given as:', '["4g IM stat", "2g IV over 20 minutes", "500mg orally", "1g IV bolus over 5 minutes"]'::jsonb, 1, 'The standard dose is 2g IV over 20 minutes, used after an hour of poor response to first-line treatment.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 55, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which of the following is not a common potential side effect of Class II Antiarrhythmic drugs (e.g. propranolol, atenolol, carvedilol)?', '["Negative inotropes", "Hypotension", "Hepatotoxicity", "Bradycardia"]'::jsonb, 2, 'Hepatotoxicity is not a typical class effect of beta-blockers, unlike bradycardia, hypotension, and negative inotropy.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 56, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Preload is best defined as:', '["The wall tension the ventricle develops during ejection", "The end-diastolic volume of the ventricle", "The intrinsic contractility of heart muscle", "The aortic diastolic pressure"]'::jsonb, 1, 'Preload is the ventricular end-diastolic volume (fibre stretch) before contraction.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 57, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Intra-abdominal hypertension is:', '["When IAP is consistently \\<12 mmHg with organ dysfunction", "When IAP is consistently \\>12 mmHg with organ dysfunction", "When IAP is \\>12 mmHg without organ dysfunction", "When IAP is consistently \\> 5 mmHg without organ dysfunction"]'::jsonb, 2, 'Intra-abdominal hypertension is defined as sustained IAP >12mmHg WITHOUT necessarily needing organ dysfunction to be present.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 58, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Droplet precautions, typically requiring a surgical mask, are appropriate for a patient with:', '["Influenza", "C. difficile infection", "MRSA colonisation", "Active pulmonary tuberculosis"]'::jsonb, 0, 'Droplet precautions with a surgical mask are used for pathogens spread via larger respiratory droplets over short distances, such as influenza.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 59, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which client is at greater risk for respiratory depression while receiving opioids for analgesia?', '["An elderly chronic pain client with a hip fracture", "A child with an arm fracture and cystic fibrosis", "A client with a heroin addiction and back pain", "A young female client with advanced multiple myeloma"]'::jsonb, 1, 'Chronic lung disease (cystic fibrosis) already compromises respiratory reserve, raising opioid depression risk.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 60, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The origin of modern intensive/critical care, including artificial ventilation, is credited to the:', '["HIV epidemic of the 1980s", "Polio epidemic of the early 1950s", "Influenza pandemic of 1918", "World War II battlefield medicine"]'::jsonb, 1, 'During the polio epidemic, patients with paralysed breathing muscles needed artificial ventilation, and this need is what led to the development of the modern ICU.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 61, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The recommended dose of neomycin in the management of PSE is:', '["500mg once weekly", "10g once daily", "1g every 6 hours", "100mg every 6 hours"]'::jsonb, 2, 'Neomycin reduces ammonia-producing gut bacteria; this is the standard dosing used in PSE management.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 62, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Ventricular compliance is defined as:', '["Change in pressure ÷ change in volume", "Cardiac output ÷ body surface area", "Change in volume ÷ change in pressure", "Stroke volume ÷ end-diastolic volume"]'::jsonb, 2, 'Compliance = change in volume ÷ change in pressure. A stiff (non-compliant) ventricle has higher filling pressure at the same volume.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 63, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which of the following is an expected reaction from a client who has just been told by the physician that his tumor is malignant and has metastasis in to several organs?', '["Crying uncontrollably", "Refusing to visit visitors", "Asking for additional medical consultations", "Criticizing medical care"]'::jsonb, 0, 'Uncontrollable crying is a normal, expected acute grief response to devastating news.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 64, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'After using a hypodermic needle, the correct action is to:', '["Bend the needle to prevent re-use, then discard it into the general waste bin", "Recap it carefully with both hands, then discard it into the yellow clinical waste", "Place it on the instrument tray so that it is removed at the end of the case", "Discard it at once, without recapping, into a sharps container at the point of use"]'::jsonb, 3, 'Most needlestick injuries happen during recapping or disposal. Sharps containers should be at the point of use and closed when three-quarters full. In theatre, use a neutral zone or tray for passing sharps.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 65, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Hepatitis C is mainly transmitted by:', '["Blood-to-blood contact", "Food and water", "Coughing and sneezing near others", "Mosquito bites"]'::jsonb, 0, 'There is no vaccine; needlestick injury is a risk.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 66, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Prions, as causes of CJD, are:', '["Viruses", "Fungi that grow in damp areas", "Abnormal infectious proteins", "Bacteria"]'::jsonb, 2, 'They resist normal sterilisation.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 67, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The patient has aphasia, decreased levels of consciousness & weakness in the right side of the body. There is a history of heart disease, ischemic attacks, and hyperlipidaemia. Based on the medical history, what type of stroke could it be?', '["Subarachnoid Haemorrhages", "Ischemic Stroke", "Intracerebral Haemorrhages", "Haemorrhagic Stroke"]'::jsonb, 1, 'Aphasia, altered consciousness, and hemiparesis with a cardiovascular risk history fits an ischaemic stroke.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 68, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'It is the monitoring of the concentration or partial pressure of carbon dioxide (CO2) in the respiratory gases.', '["Rebreathing", "Capnography", "Spirometry", "Oximetry"]'::jsonb, 1, 'Capnography monitors exhaled CO2 levels continuously.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 69, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The purpose of inserting central venous pressure (CVP) into the major vein of body such as jugular vein, subclavian vein, and femoral is to monitor the pressure in;', '["Left atrium", "Right ventricle", "Pulmonary artery", "Left ventricle"]'::jsonb, 1, 'A CVP line placed via the great veins primarily reflects right ventricular filling pressure.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 70, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The depolarization stimulus for the normal heartbeat originates in the:', '["His-bundle areas", "Epicardium", "Atrioventricular (AV) nodal", "Sinoatrial (SA) node"]'::jsonb, 3, 'The SA node is the heart''s natural pacemaker, initiating each normal beat.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 71, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The nurse is caring for a patient with respiratory failure. The nurse should prioritize which of the following positions to improve oxygenation?', '["A prone position with the head rotated to the side", "The Trendelenburg position", "A flat, supine position", "A semi-Fowler''s or high-Fowler''s position"]'::jsonb, 3, 'A semi-Fowler''s or high-Fowler''s position allows for the maximum expansion of the lungs, making it easier for the patient to breathe and improving gas exchange. The other positions can impede lung expansion and should be avoided.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 72, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The rapid shallow breathing index (RR/VT in litres) predicting weaning success is below:', '["500", "20", "300", "105"]'::jsonb, 3, 'Higher values suggest weaning failure.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 73, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'For a conscious patient after barbiturate overdose who is still breathing adequately, initial management is:', '["Observation", "Discharge immediately", "Immediate intubation regardless of breathing", "No monitoring required"]'::jsonb, 0, 'If breathing remains adequate, close observation is appropriate rather than jumping straight to invasive airway support.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 74, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'In the treatment of alcohol withdrawal there are three line management', '["Supportive, Medical procedure and Medication", "Supportive, Medication and Special procedure", "Supportive group, medical management", "Medication, Special therapy and Group therapy"]'::jsonb, 0, 'Alcohol withdrawal management follows supportive care, medical procedures, and medication together.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 75, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'On an ECG, the P wave reflects atrial depolarisation initiated by the:', '["AV node", "Bachmann''s bundle", "Left bundle branch", "SA node"]'::jsonb, 3, 'The P wave is atrial depolarisation, which the SA node initiates.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 76, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A quadriplegic patient with cervical injury is just admitted in ICU, which of this is of priority to you?', '["Multiple organs dysfunction syndrome", "Respiratory arrest", "Cardiac arrest", "Brain death"]'::jsonb, 1, 'A high cervical spinal injury directly threatens the diaphragm/respiratory muscles, making respiratory arrest the top priority.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 77, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which is NOT an ancillary investigation for brainstem death?', '["Electromyography", "Electroencephalography", "Cerebral angiography", "Transcranial Doppler"]'::jsonb, 0, 'Ancillary tests for brain death are cerebral angiography, transcranial Doppler, EEG and perfusion scans. EMG tests muscle and nerve, not the brain.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 78, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Before elective cardioversion, digoxin is usually withheld for about:', '["2 weeks", "It is never withheld", "48 hours", "1 hour"]'::jsonb, 2, 'Digoxin is usually withheld for about 48 hours before elective cardioversion because digoxin toxicity raises the risk of post-shock arrhythmias.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 79, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which device is most useful for continuous, immediate monitoring of oxygen saturation because of its simplicity?', '["Pulse oximeter", "Skin reflectance oximeter", "Ear oximeter", "Intravascular oximeter"]'::jsonb, 0, 'The finger pulse oximeter is simple, non-invasive and gives continuous, immediate SpO2 readings.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 80, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A patient with hypercalcemia is prescribed calcitonin. The nurse should monitor for:', '["Hyperphosphatemia", "Tachyphylaxis", "Hypocalcemia", "Hypoglycemia"]'::jsonb, 1, 'Calcitonin loses efficacy after 48 hours (tachyphylaxis). Hypocalcemia is rare; it primarily lowers calcium.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 81, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Excessive bubbling is seen in the water-seal chamber of a chest drain on suction. The nurse should:', '["Strip the chest tube", "Check the system for air leaks", "Decrease the suction pressure", "Recognise that the system is working correctly"]'::jsonb, 1, 'Continuous or excessive bubbling in the water-seal chamber means an air leak. Check the system from the patient down.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 82, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The main pathophysiological problem in acute severe asthma is:', '["Excess mucus production only", "Primary cardiac dysfunction", "Gas trapping with dynamic hyperinflation", "Complete airway closure with no air movement at baseline"]'::jsonb, 2, 'Air gets into the lungs through narrowed airways but can''t fully get back out, causing progressive overinflation.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 83, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A 58-year-old client with a 40-year history of smoking one to two packs of cigarettes a day has a chronic cough producing thick sputum, peripheral edema, and cyanotic nail beds. Based on this information, he most likely has which of the following conditions?', '["Emphysema", "Chronic obstructive bronchitis", "Asthma", "Adult respiratory distress syndrome (ARDS)"]'::jsonb, 1, 'A heavy smoker with chronic productive cough, oedema and cyanosis is a "blue bloater": chronic bronchitis.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 84, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The critical care nurse knows that one of the following is a thrombotic agent.', '["Heparin", "Warfarin sodium", "Clexane", "Streptokinase"]'::jsonb, 3, 'Streptokinase is a thrombolytic ("clot-busting") agent, unlike the anticoagulants listed.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 85, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Elective surgery is generally considered for cancellation when blood pressure exceeds:', '["SBP >120 AND DBP >80", "SBP >180 AND DBP >110", "Any blood pressure above normal", "SBP >100 alone"]'::jsonb, 1, 'This combined threshold (or SBP ≥200 alone) reflects a level of risk considered too high for elective proceeding without first optimising blood pressure.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 86, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'When planning an initiative to improve kidney health services in an underserved area, which factor should be prioritized?', '["Limiting service hours to reduce costs", "Increasing patient volume at existing facilities", "Enhancing community education about kidney disease prevention", "Focusing on advanced technology implementation"]'::jsonb, 2, 'The correct answer is: Enhancing community education about kidney disease prevention.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(3, 87, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Orem''s self-care deficit theory is most useful in perioperative nursing because:', '["It focuses only on the physical environment of the theatre", "It ignores the needs of the patient in favour of tasks", "It guides care when patients cannot meet their own self-care needs", "It is mainly concerned with financial management of care"]'::jsonb, 2, 'Nursing systems are wholly compensatory (e.g. under anaesthesia), partly compensatory, or supportive-educative.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(3, 88, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'The 4 skills used in evaluation are:', '["Observation, Interviewing, Record keeping, Interpretation", "Palpation, Auscultation, Percussion, Inspection", "Prescribing, Administering, Charting, Billing", "Diagnosis, Planning, Implementation, Discharge"]'::jsonb, 0, 'These four skills together let the nurse gather and make sense of information about how the patient is progressing.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(3, 89, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Which framework helps the nurse organise data collected from the patient?', '["Gordon''s functional health patterns", "Roy''s adaptation model", "Maslow''s hierarchy", "Nightingale''s environmental theory"]'::jsonb, 0, 'Gordon''s functional health patterns give a framework for organising assessment data.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(3, 90, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Orem categorized self-care requisites into three types. Which of the following correctly lists them?', '["Focal, contextual, and residual self-care requisites", "Physiological, psychological, and spiritual self-care requisites", "Universal, developmental, and health-deviation self-care requisites", "Primary, secondary, and tertiary self-care requisites"]'::jsonb, 2, 'Orem identified universal self-care requisites (common to all humans, e.g., air, water, food), developmental self-care requisites (associated with developmental processes/life events), and health-deviation self-care requisites (arising from illness or injury).', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(3, 91, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Interpersonal relationship theory was propounded by', '["B.F. skinner", "Hildegard Peplau", "Martha Rogers.", "Sigmoid Freud."]'::jsonb, 1, 'Hildegard Peplau developed the interpersonal relations theory of nursing.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(3, 92, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Which of the following NANDA-I diagnoses is classified as a ''Health Promotion'' diagnosis rather than a problem-focused or risk diagnosis?', '["Ineffective Coping", "Decisional Conflict", "Readiness for Enhanced Coping", "Risk for Ineffective Coping"]'::jsonb, 2, 'Health promotion diagnoses describe a patient''s motivation and desire to increase well-being; Readiness for Enhanced Coping reflects a patient actively wanting to strengthen an already adequate coping pattern.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(3, 93, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'A collaborative problem is one that:', '["Needs nursing and medical care, e.g. haemorrhage", "Is managed by nurses alone without any doctor", "Needs no intervention because it will resolve", "Is the responsibility of the patient''s family"]'::jsonb, 0, 'Nurses monitor and detect complications and implement medical orders.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(3, 94, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'A nurse recognizes that socioeconomic status can significantly impact kidney health. Which factor is most directly associated with increased risk for kidney disease?', '["Employment in the healthcare field", "Limited access to healthcare and nutritious foods", "Educational attainment", "High level of physical activity"]'::jsonb, 1, 'The correct answer is: Limited access to healthcare and nutritious foods.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(3, 95, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Maslow''s hierarchy of needs places which at the base?', '["Love and belonging", "Physiological needs", "Esteem", "Self-actualisation"]'::jsonb, 1, 'In perioperative care, airway, breathing and circulation take priority.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(3, 96, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'During evaluation you find two client goals have not been met. What is the best action?', '["Discharge the client", "Assess only the client''s motivation", "Reassess the problem, review the care plan and revise as needed", "Stop working on these goals, as evaluation is the last step"]'::jsonb, 2, 'When goals are not met, the nurse reassesses, finds out why, and revises the care plan. The nursing process is cyclical.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(3, 97, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Leininger''s transcultural nursing theory is relevant in theatre because:', '["It focuses only on the cultural needs of surgeons and doctors", "It is about the equipment and technology used in theatre", "Culture does not affect patient care in the operating theatre", "Care must respect cultural beliefs, e.g. about blood and modesty"]'::jsonb, 3, 'Culturally congruent care improves trust and compliance.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(3, 98, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Patient education before surgery should include:', '["Deep breathing, coughing, early mobilisation and pain control", "Financial planning for the cost of the hospital stay", "Only the details of the surgical technique to be used", "Nothing at all, because patients forget what they are told"]'::jsonb, 0, 'Preoperative education reduces anxiety and complications.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(3, 99, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Documentation in the perioperative care plan is important because:', '["It is optional when the theatre is very busy", "It only helps the surgeons write their notes", "It is only needed for the yearly audit report", "It is legal evidence and ensures continuity of care"]'::jsonb, 3, 'Undocumented care is legally considered not done.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(3, 100, 'Nephrology Nursing Mock — Day 7 Night (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'In creating a care plan for a patient undergoing hemodialysis, which aspect is most crucial to ensure effective patient outcomes?', '["Frequency of dialysis sessions", "Patient''s understanding of the dialysis process and self-care", "Strict adherence to the schedule without flexibility", "Focusing on medication administration only"]'::jsonb, 1, 'The correct answer is: Patient''s understanding of the dialysis process and self-care.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues');
