-- Nephrology Nursing mock exams — Day 7 (2026-11-11): 300 questions in 3 papers of 100.
--   Morning (08:00–10:00): NNP 417 · Medical-Surgical Nephrology I, NNP 421 · Medical-Surgical Nephrology II, NNP 412 · Applied Biochemistry
--   Afternoon (12:00–14:00): NNP 423 · Paediatric Nephrology, NNP 422 · Gynaecology and Obstetrics in Nephrology, NNP 413 · Applied Pharmacology
--   Night (19:00–21:00): Comprehensive Revision (Critical Care, Emergencies & Infection Control), NNP 425 · Advanced Nursing Concepts & Contemporary Issues
-- The questions are added as hidden exam-only questions (not shown in the practice app). The exams are
-- created for the NEPHROLOGY NURSING section only (specialty = 'neph'), so students of other sections never see them.
-- Times (Nigeria time) can be changed later on the admin page. If an exam already exists, only its
-- questions are updated. Safe to run more than once.
set lock_timeout = '5s';
begin;
create temporary table ponew (paper int, n int, source text, topic text, q text, opts jsonb, ans_idx int, exp text, category text, primary key (paper, n)) on commit drop;
select (select coalesce(max(id), 0) from public.questions) + row_number() over (order by d.paper, d.n), d.topic, d.source, d.q, d.opts, d.ans_idx, d.exp, d.category, '🩺', false
from ponew d
where not exists (select 1 from public.questions x where x.source = d.source and x.q = d.q);
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 1), instructions = 'Nephrology Nursing — Day 7 Morning. 100 questions: NNP 417 · Medical-Surgical Nephrology I, NNP 421 · Medical-Surgical Nephrology II, NNP 412 · Applied Biochemistry. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'neph'
 where title = 'Nephrology Nursing Mock — Day 7 Morning (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Nephrology Nursing Mock — Day 7 Morning (100 Questions)', 'Nephrology Nursing — Day 7 Morning. 100 questions: NNP 417 · Medical-Surgical Nephrology I, NNP 421 · Medical-Surgical Nephrology II, NNP 412 · Applied Biochemistry. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-11 08:00:00+01', timestamptz '2026-11-11 10:00:00+01', 100, (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 1),
       true, true, 100, true, true, 1, 'relaxed', 'neph'
where not exists (select 1 from public.exam_exams where title = 'Nephrology Nursing Mock — Day 7 Morning (100 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 2), instructions = 'Nephrology Nursing — Day 7 Afternoon. 100 questions: NNP 423 · Paediatric Nephrology, NNP 422 · Gynaecology and Obstetrics in Nephrology, NNP 413 · Applied Pharmacology. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'neph'
 where title = 'Nephrology Nursing Mock — Day 7 Afternoon (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Nephrology Nursing Mock — Day 7 Afternoon (100 Questions)', 'Nephrology Nursing — Day 7 Afternoon. 100 questions: NNP 423 · Paediatric Nephrology, NNP 422 · Gynaecology and Obstetrics in Nephrology, NNP 413 · Applied Pharmacology. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-11 12:00:00+01', timestamptz '2026-11-11 14:00:00+01', 100, (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 2),
       true, true, 100, true, true, 1, 'relaxed', 'neph'
where not exists (select 1 from public.exam_exams where title = 'Nephrology Nursing Mock — Day 7 Afternoon (100 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 3), instructions = 'Nephrology Nursing — Day 7 Night. 100 questions: Comprehensive Revision (Critical Care, Emergencies & Infection Control), NNP 425 · Advanced Nursing Concepts & Contemporary Issues. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'neph'
 where title = 'Nephrology Nursing Mock — Day 7 Night (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Nephrology Nursing Mock — Day 7 Night (100 Questions)', 'Nephrology Nursing — Day 7 Night. 100 questions: Comprehensive Revision (Critical Care, Emergencies & Infection Control), NNP 425 · Advanced Nursing Concepts & Contemporary Issues. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-11 19:00:00+01', timestamptz '2026-11-11 21:00:00+01', 100, (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 3),
       true, true, 100, true, true, 1, 'relaxed', 'neph'
where not exists (select 1 from public.exam_exams where title = 'Nephrology Nursing Mock — Day 7 Night (100 Questions)');
select title, specialty, cardinality(question_ids) as questions, starts_at, ends_at
  from public.exam_exams where title like 'Nephrology Nursing Mock — Day 7 %' order by starts_at;
commit;
